    public function fetch_markets($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_markets(...))($params);
    }

    private function do_fetch_markets($params = array()) {
        /**
         * retrieves data on all active $markets, each becomes one market with its two sides listed under the outcomes key
         *
         * @see https://docs.sx.bet/api-reference/get-$markets-active
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->limit] max number of $markets to collect (defaults to options.marketsPageSize * options.maxMarketsPages, 5000)
         * @return {array[]} an array of objects representing market data
         */
        $rest = $this->omit($params, array( 'limit' ));
        $userLimit = $this->safe_integer($params, 'limit');
        $rawMarkets = Async\await($this->fetch_raw_markets_paged($rest, $userLimit));
        $markets = array();
        $rawMarketsLength = count($rawMarkets);
        for ($i = 0; $i < $rawMarketsLength; $i++) {
            $markets[] = $this->parse_sxbet_market($rawMarkets[$i]);
        }
        $marketsLength = count($markets);
        if (($userLimit !== null) && ($marketsLength > $userLimit)) {
            return $this->array_slice($markets, 0, $userLimit);
        }
        return $markets;
    }

    public function fetch_raw_markets_paged(array $extra = array(), ?int $userLimit = null): PromiseInterface {
        return Async\async(self::do_fetch_raw_markets_paged(...))($extra, $userLimit);
    }

    private function do_fetch_raw_markets_paged(array $extra = array(), ?int $userLimit = null) {
        /**
         * @ignore
         * pages through GET /markets/active (cursor-based via paginationKey/nextKey), stopping once options.maxMarketsPages pages or $userLimit raw markets have been collected
         * @param {array} [$extra] $extra $request params merged into every $page (e.g. leagueId, sportId, sportXeventId)
         * @param {int} [$userLimit] stop collecting once this many raw markets have been gathered
         * @return {array[]} the raw (unparsed) sx.bet market objects
         */
        $pageSize = $this->safe_integer($this->options, 'marketsPageSize', 100);
        $maxPages = $this->safe_integer($this->options, 'maxMarketsPages', 50);
        $rawMarkets = array();
        $paginationKey = null;
        $page = 0;
        while (true) {
            $request = array( 'pageSize' => $pageSize );
            if ($paginationKey !== null) {
                $request['paginationKey'] = $paginationKey;
            }
            $response = Async\await($this->sxbetPublicGetMarketsActive($this->extend($request, $extra)));
            $result = $this->safe_dict($response, 'data', array());
            $pageMarkets = $this->safe_list($result, 'markets', array());
            $pageMarketsLength = count($pageMarkets);
            for ($i = 0; $i < $pageMarketsLength; $i++) {
                $rawMarkets[] = $pageMarkets[$i];
            }
            $paginationKey = $this->safe_string($result, 'nextKey');
            $page = $this->sum($page, 1);
            $collectedLength = count($rawMarkets);
            if (($pageMarketsLength < $pageSize) || ($page >= $maxPages) || ($paginationKey === null) || (($userLimit !== null) && ($collectedLength >= $userLimit))) {
                break;
            }
        }
        return $rawMarkets;
    }

    public function filter_raw_markets_by_fixture(array $rawMarkets, string $sportXeventId): array {
        /**
         * @ignore
         * keeps only the $raw markets belonging to one fixture — the venue's own $sportXeventId filter on /markets/active is unreliable (observed live returning every fixture), so the scope is enforced client-side
         * @param {array[]} $rawMarkets the $raw sx.bet market objects
         * @param {string} $sportXeventId the fixture id to keep
         * @return {array[]} the $raw markets of that fixture only
         */
        $result = array();
        $rawMarketsLength = count($rawMarkets);
        for ($i = 0; $i < $rawMarketsLength; $i++) {
            $raw = $rawMarkets[$i];
            if ($this->safe_string($raw, 'sportXeventId') === $sportXeventId) {
                $result[] = $raw;
            }
        }
        return $result;
    }

    public function parse_sxbet_market(array $raw): array {
        /**
         * @ignore
         * converts a single $raw sx.bet market into one ccxt market whose two sides become the $outcomes
         * @param {array} $raw the $raw sx.bet market object
         * @return {array} a [market structure](https://docs.ccxt.com/#/?id=market-structure)
         */
        //
        //     {
        //         "status": "ACTIVE",
        //         "marketHash": "0x7154aa3580267e276cccd0f4f826464a05e3efd8e1c81d7717bef6b5ae88b07d",
        //         "outcomeOneName": "Los Angeles Rams",
        //         "outcomeTwoName": "San Francisco 49ers",
        //         "outcomeVoidName": "NO_CONTEST",
        //         "teamOneName": "Los Angeles Rams",
        //         "teamTwoName": "San Francisco 49ers",
        //         "type": 226,
        //         "gameTime": 1789086900,
        //         "line": -2.5, // present on spread/total markets only
        //         "sportXeventId": "L18870109",
        //         "liveEnabled": true,
        //         "sportLabel": "Football",
        //         "sportId": 8,
        //         "leagueId": 243,
        //         "leagueLabel": "NFL",
        //         "mainLine": true,
        //         "isQuarterLineMarket": false
        //     }
        //
        $marketHash = $this->safe_string($raw, 'marketHash', '');
        $teamOneName = $this->safe_string($raw, 'teamOneName');
        $teamTwoName = $this->safe_string($raw, 'teamTwoName');
        $outcomeOneName = $this->safe_string($raw, 'outcomeOneName');
        $outcomeTwoName = $this->safe_string($raw, 'outcomeTwoName');
        $eventSlug = $this->shorten_slug($teamOneName . ' ' . $teamTwoName);
        // one fixture carries many markets (moneyline, several spread/total lines, quarter/half
        // variants) whose outcomeOneName text can coincide or nearly coincide, so a text-only
        // slug isn't guaranteed unique. suffix with the market hash instead (always unique,
        // letters+digits only so it survives shortenSlug in one atomic word)
        // parseToInt-wrapped .length: the bare `const n = str.length;` statement is the php
        // transpiler's ARRAY hint (count()), which breaks on a string — this form emits
        // strlen()/len() correctly in both python and php
        $hashLength = $this->parse_to_int(strlen($marketHash));
        $hashSuffix = mb_substr($marketHash, $hashLength - 6);
        $marketSlug = $this->shorten_slug($outcomeOneName) . '_' . $hashSuffix;
        $marketSymbol = $this->slug_to_market_symbol($eventSlug, $marketSlug);
        $status = $this->safe_string_upper($raw, 'status');
        $active = ($status === 'ACTIVE');
        // guard against a zero sentinel for "no scheduled game time" - safeTimestamp would
        // turn it into the 1970 epoch
        $gameTime = null;
        if ($this->safe_integer($raw, 'gameTime', 0) !== 0) {
            $gameTime = $this->safe_timestamp($raw, 'gameTime');
        }
        $outcomeLabels = array( $outcomeOneName, $outcomeTwoName );
        $outcomeIds = array( $marketHash, $marketHash . '-2' );
        $outcomes = array();
        for ($oi = 0; $oi < count($outcomeLabels); $oi++) {
            $label = $outcomeLabels[$oi];
            $outcomeHandle = $this->slug_to_outcome_symbol($eventSlug, $marketSlug, $label);
            $outcomes[] = array(
                'id' => $outcomeIds[$oi],
                'outcomeId' => $outcomeIds[$oi],
                'outcome' => $outcomeHandle,
                'market' => $marketSymbol,
                'label' => $label,
                'active' => $active,
                'winner' => null,
                'settleFraction' => null,
                'info' => $raw,
            );
        }
        return array(
            'id' => $marketHash,
            'market' => $marketSymbol,
            'base' => 'USDC',
            'quote' => 'USDC',
            'settle' => null,
            'baseId' => $marketHash,
            'quoteId' => 'USDC',
            'settleId' => null,
            'type' => 'prediction',
            'marketType' => 'binary',
            'executionModel' => 'clob',
            'spot' => false,
            'margin' => false,
            'swap' => false,
            'future' => false,
            'option' => false,
            'prediction' => true,
            'active' => $active,
            'resolved' => false,
            'resolvedOutcome' => null,
            'contract' => false,
            'linear' => null,
            'inverse' => null,
            'contractSize' => null,
            'expiry' => $gameTime,
            'expiryDatetime' => $this->iso8601($gameTime),
            'strike' => null,
            'optionType' => null,
            // no trading-fee percentage found anywhere in the docs/metadata (oracleFees is a
            // resolution/oracle fee, not a per-trade maker/taker cut) - 0 until live data says otherwise
            'taker' => 0,
            'maker' => 0,
            'percentage' => true,
            'tierBased' => false,
            'feeSide' => 'get',
            'precision' => array(
                // USDC stakes have 6 decimals; prices sit on the odds ladder (oddsLadderStepSize
                // 125 in 1e-5 units on both networks — see /metadata), i.e. a 0.00125 step
                'amount' => 0.000001,
                'price' => 0.00125,
            ),
            'limits' => array(
                'leverage' => array( 'min' => 1, 'max' => 1 ),
                // /metadata/obv3 publishes limits.orderSizeMinimum '1' (1 USDC, 1000000 base units)
                // on both networks - the stake and its cost share the same floor
                'amount' => array( 'min' => 1, 'max' => null ),
                'price' => array( 'min' => 0, 'max' => 1 ),
                'cost' => array( 'min' => 1, 'max' => null ),
            ),
            'outcomes' => $outcomes,
            'info' => $raw,
            'created' => null,
        );
    }

