    private function do_fetch_events($params = array()) {
        /**
         * fetches sx.bet fixtures (one fixture = one $event, its markets are every moneyline/spread/total line on that fixture) scoped by $eventId, $leagueId, $sportId or a free-text query/tags match against team and league names — always live from the API, never the local cache (it POPULATES the cache for later $event()/outcome lookups). query/queries/tags are matched client-side over a bounded scan of /markets/active — the venue's GET /search covers team names only (not league or sport labels) and is not wired here yet
         *
         * @see https://docs.sx.bet/api-reference/get-markets-active
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->eventId] direct lookup by unified $event id (the sx.bet $sportXeventId, e.g. 'L18870109')
         * @param {string} [$params->query] free-text search matched against team and league names
         * @param {string[]} [$params->queries] multiple free-text searches (alternative to query, unioned)
         * @param {string[]} [$params->tags] matched identically to query/queries (sx.bet has no tag taxonomy)
         * @param {int} [$params->leagueId] sx.bet league id (e.g. 243 for NFL) — fetched server-side
         * @param {int} [$params->sportId] sx.bet sport id (e.g. 8 for Football) — fetched server-side
         * @param {string} [$params->status] 'active' | 'inactive' | 'closed' | 'all'
         * @param {int} [$params->limit] max number of events to return
         * @return {array[]} an array of $event structures
         */
        $this->require_event_query($params);
        $eventId = $this->safe_string_2($params, 'eventId', 'slug');
        $leagueId = $this->safe_string($params, 'leagueId');
        $sportId = $this->safe_string($params, 'sportId');
        $queries = $this->parse_search_queries($params);
        $tags = $this->safe_list($params, 'tags', array());
        $tagsLength = count($tags);
        for ($i = 0; $i < $tagsLength; $i++) {
            $queries[] = $tags[$i];
        }
        $rest = $this->omit($params, array( 'eventId', 'slug', 'leagueId', 'sportId', 'query', 'queries', 'tags', 'status', 'sort', 'searchIn', 'limit' ));
        if ($eventId !== null) {
            $rawMarkets = Async\await($this->fetch_raw_markets_paged($this->extend(array( 'sportXeventId' => $eventId ), $rest), null));
            // the venue's sportXeventId filter on /markets/active is unreliable (observed live
            // returning every fixture) — enforce the scope client-side
            $rawMarkets = $this->filter_raw_markets_by_fixture($rawMarkets, $eventId);
        } elseif ($leagueId !== null) {
            $rawMarkets = Async\await($this->fetch_raw_markets_paged($this->extend(array( 'leagueId' => $leagueId ), $rest), null));
        } elseif ($sportId !== null) {
            $rawMarkets = Async\await($this->fetch_raw_markets_paged($this->extend(array( 'sportId' => $sportId ), $rest), null));
        } else {
            // no server-side scope left, only query/tags — full scan honoring the fetchMarkets
            // bound, then filter client-side (the venue's /search covers team names only)
            $rawMarkets = Async\await($this->fetch_raw_markets_paged($rest, null));
        }
        $queriesLength = count($queries);
        if ($queriesLength > 0) {
            $filtered = array();
            $preFilterLength = count($rawMarkets);
            for ($i = 0; $i < $preFilterLength; $i++) {
                if ($this->matches_event_query($rawMarkets[$i], $queries)) {
                    $filtered[] = $rawMarkets[$i];
                }
            }
            $rawMarkets = $filtered;
        }
        $grouped = array();
        $order = array();
        $rawMarketsLength = count($rawMarkets);
        for ($i = 0; $i < $rawMarketsLength; $i++) {
            $raw = $rawMarkets[$i];
            $sportXeventId = $this->safe_string($raw, 'sportXeventId');
            if ($sportXeventId === null) {
                continue;
            }
            if (!(is_array($grouped) && array_key_exists($sportXeventId ?? '', $grouped))) {
                $grouped[$sportXeventId] = array();
                $order[] = $sportXeventId;
            }
            $grouped[$sportXeventId][] = $raw;
        }
        if ($this->markets === null) {
            $this->markets = $this->create_safe_dictionary();
        }
        $result = array();
        $orderLength = count($order);
        for ($i = 0; $i < $orderLength; $i++) {
            $fixtureId = $order[$i];
            $event = $this->parse_event($fixtureId, $grouped[$fixtureId]);
            $evMarkets = $this->safe_list($event, 'markets', array());
            $evMarketsLength = count($evMarkets);
            for ($j = 0; $j < $evMarketsLength; $j++) {
                $m = $evMarkets[$j];
                $this->markets[$m['market']] = $m;
            }
            $result[] = $event;
        }
        $this->populate_outcomes();
        $this->set_events($result);
        $postParams = $this->omit($params, array( 'leagueId', 'sportId', 'query', 'queries', 'tags' ));
        return $this->apply_event_fetch_params($result, $postParams, array());
    }

    public function fetch_event(string $id, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_event(...))($id, $params);
    }

    private function do_fetch_event(string $id, $params = array()) {
        /**
         * fetches a single sx.bet fixture ($event) by its sportXeventId
         *
         * @see https://docs.sx.bet/api-reference/get-markets-active
         *
         * @param {string} $id the sx.bet sportXeventId, e.g. 'L18870109'
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a [prediction $event structure](https://docs.ccxt.com/#/?$id=prediction-$event-structure)
         */
        $rawMarkets = Async\await($this->fetch_raw_markets_paged($this->extend(array( 'sportXeventId' => $id ), $params), null));
        // enforce the fixture scope client-side — see filterRawMarketsByFixture
        $rawMarkets = $this->filter_raw_markets_by_fixture($rawMarkets, $id);
        $rawMarketsLength = count($rawMarkets);
        if ($rawMarketsLength === 0) {
            throw new BadSymbol($this->id . ' fetchEvent() could not find an active fixture ' . $id);
        }
        $event = $this->parse_event($id, $rawMarkets);
        $this->index_event_outcomes($event);
        $this->set_events(array( $event ));
        return $event;
    }

    public function matches_event_query(array $raw, array $queries): bool {
        /**
         * @ignore
         * checks a $raw market's team/league names against a list of free-text $queries, matching in either direction (a short user $query inside a long name, or — since fetchEvents derives its fallback test $query from an already-slugified handle — a long joined $query containing a short name)
         * @param {array} $raw the $raw sx.bet market object
         * @param {string[]} $queries lowercase-insensitive free-text $queries
         * @return {boolean} whether any $query matches any of the market's team/league/outcome names
         */
        $fields = array(
            $this->safe_string($raw, 'teamOneName'),
            $this->safe_string($raw, 'teamTwoName'),
            $this->safe_string($raw, 'leagueLabel'),
            $this->safe_string($raw, 'sportLabel'),
            $this->safe_string($raw, 'outcomeOneName'),
            $this->safe_string($raw, 'outcomeTwoName'),
        );
        $queriesLength = count($queries);
        for ($qi = 0; $qi < $queriesLength; $qi++) {
            $query = strtolower($queries[$qi]);
            if ($query === '') {
                continue;
            }
            for ($fi = 0; $fi < count($fields); $fi++) {
                $field = $fields[$fi];
                if ($field === null) {
                    continue;
                }
                $fieldLower = strtolower($field);
                if ((mb_strpos($query, $fieldLower) !== false) || (mb_strpos($fieldLower, $query) !== false)) {
                    return true;
                }
            }
        }
        return false;
    }

    public function parse_event(string $fixtureId, array $rawMarkets): mixed {
        /**
         * @ignore
         * groups a fixture's $raw markets (all sharing one sportXeventId) into one unified event structure
         * @param {string} $fixtureId the sx.bet sportXeventId
         * @param {array[]} $rawMarkets the $raw sx.bet market objects belonging to this fixture
         * @return {array} an event structure
         */
        $marketsList = array();
        $anyActive = false;
        $earliestGameTime = null;
        $teamOneName = null;
        $teamTwoName = null;
        $leagueLabel = null;
        $rawMarketsLength = count($rawMarkets);
        for ($i = 0; $i < $rawMarketsLength; $i++) {
            $raw = $rawMarkets[$i];
            $parsed = $this->parse_sxbet_market($raw);
            if ($parsed === null) {
                throw new ExchangeError($this->id . ' parseEvent() could not resolve $parsed market');
            }
            $marketsList[] = $parsed;
            if ($parsed['active'] === true) {
                $anyActive = true;
            }
            if ($teamOneName === null) {
                $teamOneName = $this->safe_string($raw, 'teamOneName');
                $teamTwoName = $this->safe_string($raw, 'teamTwoName');
                $leagueLabel = $this->safe_string($raw, 'leagueLabel');
            }
            $gameTime = $this->safe_string($raw, 'gameTime');
            // skip the zero sentinel for "no scheduled game time" so it can't become the epoch
            if (($gameTime !== null) && ($gameTime !== '0') && (($earliestGameTime === null) || ($gameTime < $earliestGameTime))) {
                $earliestGameTime = $gameTime;
            }
        }
        $end = $this->safe_timestamp(array( 'gameTime' => $earliestGameTime ), 'gameTime');
        // some fixtures carry no team names on their market rows - fall back to the fixture id
        // so the unified event handle is never empty or built from stringified nulls
        $title = null;
        $eventSlug = null;
        if (($teamOneName !== null) && ($teamTwoName !== null)) {
            $title = $teamOneName . ' vs ' . $teamTwoName;
            $eventSlug = $this->shorten_slug($teamOneName . ' ' . $teamTwoName);
        } else {
            $eventSlug = $this->shorten_slug($fixtureId);
        }
        return array(
            'id' => $fixtureId,
            'slug' => $fixtureId,
            'event' => $eventSlug,
            'title' => $title,
            'description' => null,
            'category' => $leagueLabel,
            'tags' => null,
            'markets' => $marketsList,
            'mutuallyExclusive' => false,
            'active' => $anyActive,
            'resolved' => null,
            'volume' => null,
            'liquidity' => null,
            'created' => null,
            'createdDatetime' => null,
            'end' => $end,
            'endDatetime' => $this->iso8601($end),
            'image' => null,
            'url' => null,
            'info' => $rawMarkets,
        );
    }

    public function load_sx_obv3_metadata(): PromiseInterface {
        return Async\async(self::do_load_sx_obv3_metadata(...))();
    }

    private function do_load_sx_obv3_metadata() {
        /**
         * @ignore
         * fetches and caches GET /metadata/obv3 - the v3 orderbook metadata carrying the ready-made EIP-712 domain, the active base asset and the order size limits
         *
         * @see https://docs.sx.bet/api-reference/get-metadata-obv3
         *
         * @return {array} the $cached obv3 metadata $data object
         */
        $cached = $this->safe_dict($this->options, 'sxObv3Metadata');
        if ($cached !== null) {
            return $cached;
        }
        $response = Async\await($this->sxbetPublicGetMetadataObv3());
        $data = $this->safe_dict($response, 'data', array());
        $this->options['sxObv3Metadata'] = $data;
        return $data;
    }

    public function round_odds_to_ladder(?string $probability, string $oddsLadderStepSize): string {
        /**
         * @ignore
         * rounds an implied $probability (0-1) to sx.bet's odds ladder ($oddsLadderStepSize is in units of 1e-5, e.g. 125 -> a 0.125% step) — a maker's percentageOdds is rejected unless it lands exactly on the ladder
         * @param {string} $probability the implied $probability in decimal-string form (0-1)
         * @param {string} $oddsLadderStepSize the raw $oddsLadderStepSize from /metadata/obv3 (e.g. '125')
         * @return {string} the $probability rounded to the nearest ladder step, in decimal-string form
         */
        $tickSize = Precise::string_div($oddsLadderStepSize, '100000', 10);
        return $this->decimal_to_precision($probability, ROUND, $tickSize, TICK_SIZE);
    }

    public function hash_eip712_digest(mixed $encoded): string {
        /**
         * @ignore
         * hashes an EIP-712 $encoded payload (domainSeparator‖structHash, prefixed with 0x1901 by ethEncodeStructuredData) down to the final 32-byte digest to sign, used by sx.bet's taker-fill and cancel signatures
         * @param {Uint8Array} $encoded the output of $this->eth_encode_structured_data(domain, types, message)
         * @return {string} the 32-byte digest to ecdsa-sign, in '0x'-prefixed hex form
         */
        return '0x' . $this->hash($encoded, 'keccak', 'hex');
    }

    public function sign_digest(string $digest, string $privateKey): string {
        /**
         * @ignore
         * ecdsa-signs a 32-byte $digest and assembles the $r‖$s‖$v hex $signature sx.bet expects
         * @param {string} $digest the '0x'-prefixed 32-byte $digest to sign
         * @param {string} $privateKey the signer's private key
         * @return {string} a '0x'-prefixed 65-byte hex $signature ($r‖$s‖$v)
         */
        $signature = $this->ecdsa(mb_substr($digest, -64), mb_substr($privateKey, -64), 'secp256k1', null);
        // assign to bare locals before padStart — the php transpiler's str_pad regex only
        // matches a simple identifier, an expression form leaks a raw padStart() call
        $rRaw = $signature['r'];
        $sRaw = $signature['s'];
        $r = str_pad($rRaw, 64, '0', STR_PAD_LEFT);
        $s = str_pad($sRaw, 64, '0', STR_PAD_LEFT);
        $v = $this->int_to_base16($this->sum(27, $signature['v']));
        return '0x' . $r . $s . $v;
    }

    public function fetch_erc20_name(?string $rpcUrl, string $tokenAddress): PromiseInterface {
        return Async\async(self::do_fetch_erc20_name(...))($rpcUrl, $tokenAddress);
    }

    private function do_fetch_erc20_name(?string $rpcUrl, string $tokenAddress) {
        /**
         * @ignore
         * reads an ERC20 token's name() via eth_call (needed for the Permit EIP-712 domain — must match the token's real on-chain name or the signature fails verification)
         * @param {string} $rpcUrl the RPC endpoint to call
         * @param {string} $tokenAddress the token contract address
         * @return {string} the token's on-chain name
         */
        $nameCallData = '0x06fdde03'; // name()
        $result = Async\await($this->eth_rpc($rpcUrl, 'eth_call', array( array( 'to' => $tokenAddress, 'data' => $nameCallData ), 'latest' )));
        $hex = $this->remove0x_prefix($result);
        // dynamic ABI string return: [32-byte offset][32-byte length][utf8 bytes, right-padded]
        $lengthHex = mb_substr($hex, 64, 128 - 64);
        $length = $this->hex_to_int($lengthHex);
        $dataEnd = $this->sum(128, $length * 2);
        $dataHex = mb_substr($hex, 128, $dataEnd - 128);
        return $this->decode($this->base16_to_binary($dataHex));
    }

    public function hex_to_int(string $hex): float {
        /**
         * @ignore
         * parses a $hex string (no '0x' prefix) into an integer — plain digit-by-digit, since JS's parseInt ($hex, 16) two-argument form has no portable equivalent across languages/transpilers. Only used for small values (byte lengths, permit nonces), safe well within the float-precision range
         * @param {string} $hex the $hex string, no '0x' prefix
         * @return {int} the parsed integer
         */
        $digits = '0123456789abcdef';
        $lowerHex = strtolower($hex);
        $hexLength = count($lowerHex);
        $result = 0;
        for ($i = 0; $i < $hexLength; $i++) {
            $ch = $lowerHex[$i];
            $digitValue = mb_strpos($digits, $ch);
            $result = ($result * 16) . $digitValue;
        }
        return $result;
    }

    public function fetch_sxbet_proxy(): PromiseInterface {
        return Async\async(self::do_fetch_sxbet_proxy(...))();
    }

    private function do_fetch_sxbet_proxy() {
        /**
         * @ignore
         * fetches the account's obv3 proxy wallet state
         *
         * @see https://docs.sx.bet/api-reference/get-user-proxy
         *
         * @return {array} the raw proxy data (array(obv3ProxyWalletAddress, deployed, multisigSafeAddress))
         */
        $response = Async\await($this->sxbetPrivateGetUserProxy());
        return $this->safe_dict($response, 'data', array());
    }

    public function approve($params = array()): PromiseInterface {
        return Async\async(self::do_approve(...))($params);
    }

    private function do_approve($params = array()) {
        /**
         * funds the account's $obv3 $proxy wallet - v3 trading capital must sit inside the $proxy-> Deploys the $proxy first when absent, then moves USDC from the wallet into it via a gasless EIP-2612 Permit $signature (POST /user/transfer-to-$proxy)
         *
         * @see https://docs.sx.bet/api-reference/post-user-transfer-to-$proxy
         * @see https://docs.sx.bet/api-reference/post-user-deploy-$proxy
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {float} [$params->amount] the USDC $amount to move into the $proxy (required)
         * @param {string} [$params->tokenAddress] the token to transfer, defaults to the active base token
         * @param {string} [$params->spender] the transfer executor granted the permit, defaults to options.transferToProxySpender or the $obv3 transferToProxyExecutorAddress
         * @param {int} [$params->deadline] unix seconds the permit $signature expires at, defaults to options.approveDeadlineSeconds from now
         * @param {string} [$params->rpcUrl] overrides the chain's default RPC endpoint (see options.chains)
         * @return {array} a dict with the raw $response and the transfer sessionId
         */
        $this->check_required_credentials();
        $amount = $this->safe_number($params, 'amount');
        if ($amount === null) {
            throw new ArgumentsRequired($this->id . ' approve() requires $params->amount - the USDC $amount to move into the $proxy wallet');
        }
        $proxy = Async\await($this->fetch_sxbet_proxy());
        $deployed = $this->safe_bool($proxy, 'deployed', false);
        if ($deployed !== true) {
            Async\await($this->sxbetPrivatePostUserDeployProxy());
            // deployment is asynchronous - poll until the proxy exists
            for ($i = 0; $i < 30; $i++) {
                Async\await($this->sleep(2000));
                $state = Async\await($this->fetch_sxbet_proxy());
                if ($this->safe_bool($state, 'deployed', false)) {
                    break;
                }
            }
        }
        $obv3 = Async\await($this->load_sx_obv3_metadata());
        $activeAsset = $this->safe_dict($obv3, 'activeAsset', array());
        $chainId = $this->safe_integer($obv3, 'chainId');
        $usdcAddress = $this->safe_string($activeAsset, 'baseToken');
        // the permit spender is the venue's transfer-to-proxy executor, published in /metadata/obv3
        $executorAddress = $this->safe_string($obv3, 'transferToProxyExecutorAddress');
        $tokenAddress = $this->safe_string($params, 'tokenAddress', $usdcAddress);
        if ($tokenAddress === null) {
            throw new BadRequest($this->id . ' approve() could not resolve the base token address from /metadata/obv3');
        }
        $spender = null;
        list($spender, $params) = $this->handle_option_and_params_2($params, 'approve', 'spender', 'transferToProxySpender', $executorAddress);
        if ($spender === null) {
            throw new BadRequest($this->id . ' approve() could not resolve the transfer-to-$proxy executor from /metadata/obv3 - pass $params->spender');
        }
        $chains = $this->safe_dict($this->options, 'chains', array());
        $chainConfig = $this->safe_dict($chains, $this->number_to_string($chainId), array());
        $rpcUrl = $this->safe_string($params, 'rpcUrl', $this->safe_string($chainConfig, 'rpcUrl'));
        if ($rpcUrl === null) {
            throw new ArgumentsRequired($this->id . ' approve() has no RPC endpoint configured for $chainId ' . $this->number_to_string($chainId) . ' - pass $params->rpcUrl');
        }
        $owner = $this->walletAddress;
        $nonceCallData = '0x7ecebe00' . $this->pad_hex_address($owner); // nonces(address)
        $nonceResult = Async\await($this->eth_rpc($rpcUrl, 'eth_call', array( array( 'to' => $tokenAddress, 'data' => $nonceCallData ), 'latest' )));
        $nonceHex = $this->hex_to_rlp_bytes($nonceResult);
        $nonce = ($nonceHex === '') ? '0' : $this->number_to_string($this->hex_to_int($nonceHex));
        $tokenName = Async\await($this->fetch_erc20_name($rpcUrl, $tokenAddress));
        $defaultDeadlineSeconds = $this->safe_integer($this->options, 'approveDeadlineSeconds', 7200);
        $deadline = $this->safe_integer($params, 'deadline', $this->sum($this->seconds(), $defaultDeadlineSeconds));
        $value = $this->decimal_to_precision(Precise::string_mul($this->number_to_string($amount), '1000000'), ROUND, 0, DECIMAL_PLACES);
        $domain = array( 'name' => $tokenName, 'version' => '1', 'chainId' => $chainId, 'verifyingContract' => $tokenAddress );
        $messageTypes = array(
            'Permit' => array(
                array( 'name' => 'owner', 'type' => 'address' ),
                array( 'name' => 'spender', 'type' => 'address' ),
                array( 'name' => 'value', 'type' => 'uint256' ),
                array( 'name' => 'nonce', 'type' => 'uint256' ),
                array( 'name' => 'deadline', 'type' => 'uint256' ),
            ),
        );
        $messageData = array( 'owner' => $owner, 'spender' => $spender, 'value' => $value, 'nonce' => $nonce, 'deadline' => $deadline );
        $encoded = $this->eth_encode_structured_data($domain, $messageTypes, $messageData);
        $digest = $this->hash_eip712_digest($encoded);
        $signature = $this->sign_digest($digest, $this->privateKey);
        $request = array(
            'owner' => $owner,
            'spender' => $spender,
            'tokenAddress' => $tokenAddress,
            'value' => $value,
            'deadline' => $this->number_to_string($deadline),
            'signature' => $signature,
        );
        $rest = $this->omit($params, array( 'amount', 'tokenAddress', 'deadline', 'rpcUrl' ));
        $response = Async\await($this->sxbetPrivatePostUserTransferToProxy($this->extend($request, $rest)));
        $data = $this->safe_dict($response, 'data', array());
        return array(
            'info' => $response,
            'id' => $this->safe_string($data, 'sessionId'),
        );
    }

    public function create_order(string $outcome, ?string $type, ?string $side, ?float $amount, ?float $price = null, $params = array()): PromiseInterface {
        return Async\async(self::do_create_order(...))($outcome, $type, $side, $amount, $price, $params);
    }

    private function do_create_order(string $outcome, ?string $type, ?string $side, ?float $amount, ?float $price = null, $params = array()) {
        /**
         * places an order on sx.bet's v3 unified orderbook - a 'limit' order rests with GTC time-in-force, a 'market' order fills immediately with IOC (or FOK via $params->timeInForce). sx.bet has no shares - 'amount' is the USDC stake to risk, and 'price' is the implied $probability (0-1) of the requested $outcome-> 'sell' bets the OPPOSITE $outcome of the one requested (sx.bet is bilateral => there is no owned position to sell, only the complementary $side of the same market)
         *
         * @see https://docs.sx.bet/api-reference/post-orders-v3
         *
         * @param {string} $outcome unified $outcome or $outcome token id
         * @param {string} $type 'limit' (GTC resting order) or 'market' (IOC immediate fill)
         * @param {string} $side 'buy' backs the requested $outcome, 'sell' backs the complementary one
         * @param {float} $amount the USDC $amount to stake/risk
         * @param {float} [$price] implied $probability (0-1) of the requested $outcome; required for both order types
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->timeInForce] overrides the derived value - 'GTC', 'IOC' or 'FOK'
         * @param {int} [$params->expiry] unix seconds the order expires at; must be in the future (zero and past values are rejected, so is anything inside the fixture's betting-delay window - /metadata/obv3 resolves the delay per sport/league, live vs pregame), defaults to options.defaultOrderExpirySeconds from $now
         * @param {string} [$params->salt] overrides the random salt differentiating this order
         * @param {string} [$params->clientOrderId] caller-chosen id echoed back on reads (max 64 chars)
         * @param {boolean} [$params->waitForOutcome] wait for the matching $outcome inline (default true)
         * @param {boolean} [$params->useBetCredits] fund the stake from bet credits instead of the proxy balance (IOC/FOK only)
         * @param {string} [$params->externalUserId] partner attribution id echoed back on order, fill and trade reads
         * @return {array} a [prediction order structure](https://docs.ccxt.com/#/?id=prediction-order-structure)
         */
        $this->check_required_credentials();
        Async\await($this->load_outcome($outcome));
        $outcomeObj = $this->outcome($outcome);
        if (($type !== 'limit') && ($type !== 'market')) {
            throw new InvalidOrder($this->id . " createOrder() $type must be 'limit' or 'market', got " . $type);
        }
        if ($price === null) {
            throw new ArgumentsRequired($this->id . ' createOrder() requires a $price - the implied $probability of the requested outcome');
        }
        // the venue has no post-only or trigger mechanics - reject the unified params instead
        // of forwarding fields the exchange would silently ignore
        $postOnly = $this->safe_bool($params, 'postOnly', false);
        if ($postOnly === true) {
            throw new NotSupported($this->id . ' createOrder() does not support $postOnly - GTC orders may cross on entry');
        }
        $triggerPrice = $this->safe_string_n($params, array( 'triggerPrice', 'stopLossPrice', 'takeProfitPrice' ));
        if ($triggerPrice !== null) {
            throw new NotSupported($this->id . ' createOrder() does not support trigger, stop-loss or take-profit orders');
        }
        $marketHash = $this->safe_string($outcomeObj['info'], 'marketHash', '');
        $outcomeId = $this->safe_string($outcomeObj, 'outcomeId');
        $isOutcomeOne = ($outcomeId === $marketHash);
        $isBuy = ($side === 'buy');
        // 'sell' bets the complementary outcome, mirroring the requested outcome's own probability -
        // matches the normalize-to-one-book convention used by other prediction venues
        $isMakerBettingOutcomeOne = ($isBuy) ? $isOutcomeOne : !$isOutcomeOne;
        $priceStr = $this->number_to_string($price);
        $probability = ($isBuy) ? $priceStr : Precise::string_sub('1', $priceStr);
        $obv3 = Async\await($this->load_sx_obv3_metadata());
        $domain = $this->safe_dict($obv3, 'domain', array());
        $activeAsset = $this->safe_dict($obv3, 'activeAsset', array());
        $baseToken = $this->safe_string($activeAsset, 'baseToken');
        $oddsLadderStepSize = $this->number_to_string($this->safe_integer($obv3, 'oddsLadderStepSize', 125));
        $roundedProbability = $this->round_odds_to_ladder($probability, $oddsLadderStepSize);
        $percentageOdds = $this->decimal_to_precision(Precise::string_mul($roundedProbability, '100000000000000000000'), ROUND, 0, DECIMAL_PLACES);
        $amountStr = $this->number_to_string($amount);
        $totalBetSize = $this->decimal_to_precision(Precise::string_mul($amountStr, '1000000'), ROUND, 0, DECIMAL_PLACES);
        $saltNumber = $this->safe_string($params, 'salt', $this->number_to_string($this->milliseconds()));
        // the request body carries the salt in 32-byte-hex form; the signed struct carries the
        // same value in uint256 form - both parse to one number server-side. assign to bare locals
        // before padStart - see the transpiler notes
        $saltHexRaw = $this->int_to_base16($this->parse_to_int($saltNumber));
        $saltHexPadded = str_pad($saltHexRaw, 64, '0', STR_PAD_LEFT);
        $saltHex = '0x' . $saltHexPadded;
        $defaultExpirySeconds = $this->safe_integer($this->options, 'defaultOrderExpirySeconds', 86400);
        $expiry = $this->safe_integer($params, 'expiry', $this->sum($this->seconds(), $defaultExpirySeconds));
        $defaultTif = ($type === 'limit') ? 'GTC' : 'IOC';
        $timeInForce = null;
        list($timeInForce, $params) = $this->handle_option_and_params($params, 'createOrder', 'timeInForce', $defaultTif);
        // an explicit IOC/FOK on a 'limit' order is honored verbatim - the venue executes exactly
        // that time-in-force. only GTC on a 'market' order is refused: it would silently rest,
        // contradicting the immediate-fill semantics the type promises
        if (($type === 'market') && ($timeInForce === 'GTC')) {
            throw new InvalidOrder($this->id . " createOrder() market orders cannot be GTC - use $type 'limit' for a resting order");
        }
        $maker = $this->walletAddress;
        $messageTypes = array(
            'Order' => array(
                array( 'name' => 'marketHash', 'type' => 'bytes32' ),
                array( 'name' => 'baseToken', 'type' => 'address' ),
                array( 'name' => 'totalBetSize', 'type' => 'uint256' ),
                array( 'name' => 'percentageOdds', 'type' => 'uint256' ),
                array( 'name' => 'salt', 'type' => 'uint256' ),
                array( 'name' => 'expiry', 'type' => 'uint256' ),
                array( 'name' => 'maker', 'type' => 'address' ),
                array( 'name' => 'isMakerBettingOutcomeOne', 'type' => 'bool' ),
            ),
        );
        $messageData = array(
            'marketHash' => $marketHash,
            'baseToken' => $baseToken,
            'totalBetSize' => $totalBetSize,
            'percentageOdds' => $percentageOdds,
            'salt' => $saltNumber,
            'expiry' => $expiry,
            'maker' => $maker,
            'isMakerBettingOutcomeOne' => $isMakerBettingOutcomeOne,
        );
        $encoded = $this->eth_encode_structured_data($domain, $messageTypes, $messageData);
        $digest = $this->hash_eip712_digest($encoded);
        $orderSignature = $this->sign_digest($digest, $this->privateKey);
        $orderItem = array(
            'marketHash' => $marketHash,
            'maker' => $maker,
            'totalBetSize' => $totalBetSize,
            'percentageOdds' => $percentageOdds,
            'salt' => $saltHex,
            'expiry' => $expiry,
            'baseToken' => $baseToken,
            'isMakerBettingOutcomeOne' => $isMakerBettingOutcomeOne,
            'timeInForce' => $timeInForce,
            'orderSignature' => $orderSignature,
        );
        $clientOrderId = $this->safe_string($params, 'clientOrderId');
        if ($clientOrderId !== null) {
            $orderItem['clientOrderId'] = $clientOrderId;
        }
        // useBetCredits and externalUserId are per-order fields - route them into the order item,
        // not the top-level body, where the venue would silently ignore them
        $useBetCredits = $this->safe_bool($params, 'useBetCredits');
        if ($useBetCredits !== null) {
            $orderItem['useBetCredits'] = $useBetCredits;
        }
        $externalUserId = $this->safe_string($params, 'externalUserId');
        if ($externalUserId !== null) {
            $orderItem['externalUserId'] = $externalUserId;
        }
        $waitForOutcome = $this->safe_bool($params, 'waitForOutcome', true);
        $rest = $this->omit($params, array( 'salt', 'expiry', 'clientOrderId', 'waitForOutcome', 'useBetCredits', 'externalUserId' ));
        $request = array( 'orders' => array( $orderItem ), 'waitForOutcome' => $waitForOutcome );
        $response = Async\await($this->sxbetPrivatePostOrdersV3($this->extend($request, $rest)));
        $data = $this->safe_dict($response, 'data', array());
        $results = $this->safe_list($data, 'orders', array());
        $first = $this->safe_dict($results, 0, array());
        $status = $this->safe_string_upper($first, 'status');
        if ($status === 'FAILED') {
            $reason = $this->safe_string($first, 'reason', 'FAILED');
            $feedback = $this->id . ' createOrder() rejected => ' . $reason;
            $this->throw_exactly_matched_exception($this->exceptions['exact'], $reason, $feedback);
            throw new InvalidOrder($feedback);
        }
        // with waitForOutcome the venue reports the matching result inline:
        //     "outcome": { "state": "FULLY_FILLED", "fillAmount": "2000000", "remainingAmount": "0", "matchIds": [...] }
        // documented states: RESTED, FULLY_FILLED, PARTIAL_FILL_DONE, PARTIAL_FILL_RESTED, TIMEOUT and
        // CANCELLED with cancelReason NO_LIQUIDITY, INTERNAL_ERROR, ENGINE_SHUTDOWN, EXPIRED or INSUFFICIENT_BALANCE
        $matchOutcome = $this->safe_dict($first, 'outcome');
        $usdcDecimals = '1000000';
        $filled = null;
        $remaining = null;
        $orderStatus = null;
        if ($matchOutcome !== null) {
            $fillAmountRaw = $this->safe_string($matchOutcome, 'fillAmount');
            $remainingRaw = $this->safe_string($matchOutcome, 'remainingAmount');
            if ($fillAmountRaw !== null) {
                $filled = $this->parse_number(Precise::string_div($fillAmountRaw, $usdcDecimals, 6));
            }
            if ($remainingRaw !== null) {
                $remaining = $this->parse_number(Precise::string_div($remainingRaw, $usdcDecimals, 6));
            }
            $state = $this->safe_string_upper($matchOutcome, 'state');
            if (($state === 'RESTED') || ($state === 'PARTIAL_FILL_RESTED')) {
                $orderStatus = 'open';
            } elseif ($state === 'FULLY_FILLED') {
                $orderStatus = 'closed';
            } elseif ($state === 'PARTIAL_FILL_DONE') {
                // the unmatched remainder of an IOC was cancelled by the venue
                $orderStatus = 'canceled';
            } elseif ($state === 'CANCELLED') {
                // the documented field is cancelReason; 'reason' is kept for older responses
                $reason = $this->safe_string_upper_2($matchOutcome, 'cancelReason', 'reason');
                $orderStatus = ($reason === 'EXPIRED') ? 'expired' : 'canceled';
            }
            // TIMEOUT: the wait elapsed before matching resolved - the order state is unknown here
        }
        $now = $this->milliseconds();
        return $this->safe_prediction_order(array(
            'id' => $this->safe_string_2($first, 'orderId', 'orderHash'),
            'clientOrderId' => $this->safe_string($first, 'clientOrderId', $clientOrderId),
            'info' => $response,
            'timestamp' => $now,
            'datetime' => $this->iso8601($now),
            'status' => $orderStatus,
            'filled' => $filled,
            'remaining' => $remaining,
            'cost' => $filled,
            'outcome' => $this->safe_string($outcomeObj, 'outcome'),
            'outcomeId' => $outcomeId,
            'label' => $this->safe_string($outcomeObj, 'label'),
            'market' => $this->safe_string($outcomeObj, 'market'),
            'type' => $type,
            'timeInForce' => $timeInForce,
            'side' => $side,
            'price' => $this->parse_number($roundedProbability),
            'amount' => $amount,
            'fee' => null,
            'trades' => array(),
        ), $outcomeObj);
    }

    public function parse_sxbet_cancel_response(array $response): array {
        /**
         * @ignore
         * parses the shared v3 cancel $response (array($cancelled, $notCancelled, $unconfirmed)) into order structures
         * @param {array} $response the raw DELETE /orders-v3 $response
         * @return {array[]} a list of [prediction order structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
         */
        $data = $this->safe_dict($response, 'data', array());
        $result = array();
        // by-id cancels report 'cancelled'; the /all and /event paths submit asynchronously and
        // report 'cancelledSubmitted' instead - treat both like cancelled
        $cancelled = $this->safe_list_2($data, 'cancelled', 'cancelledSubmitted', array());
        $cancelledLength = count($cancelled);
        for ($i = 0; $i < $cancelledLength; $i++) {
            $result[] = $this->safe_prediction_order(array(
                'id' => $this->safe_string($cancelled[$i], 'orderId'),
                'status' => 'canceled',
                'info' => $response,
            ));
        }
        $notCancelled = $this->safe_list($data, 'notCancelled', array());
        $notCancelledLength = count($notCancelled);
        for ($i = 0; $i < $notCancelledLength; $i++) {
            // the venue reports why (e.g. NOT_FOUND) - the order was not cancelled, report it honestly
            $result[] = $this->safe_prediction_order(array(
                'id' => $this->safe_string($notCancelled[$i], 'orderId'),
                'status' => null,
                'info' => $response,
            ));
        }
        $unconfirmed = $this->safe_list($data, 'unconfirmed', array());
        $unconfirmedLength = count($unconfirmed);
        for ($i = 0; $i < $unconfirmedLength; $i++) {
            $result[] = $this->safe_prediction_order(array(
                'id' => $this->safe_string($unconfirmed[$i], 'orderId'),
                'status' => null,
                'info' => $response,
            ));
        }
        return $result;
    }

    public function cancel_order(string $id, ?string $outcome = null, $params = array()): PromiseInterface {
        return Async\async(self::do_cancel_order(...))($id, $outcome, $params);
    }

    private function do_cancel_order(string $id, ?string $outcome = null, $params = array()) {
        /**
         * cancels one resting maker order - v3 cancels are plain api-key-authenticated DELETE requests, no signature involved
         *
         * @see https://docs.sx.bet/api-reference/delete-$orders-v3
         *
         * @param {string} $id the order $id
         * @param {string} [$outcome] not used by sxbet.cancelOrder
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a [prediction order structure](https://docs.ccxt.com/#/?$id=prediction-order-structure)
         */
        $this->check_required_credentials();
        $request = array( 'orders' => array( array( 'orderId' => $id ) ) );
        $response = Async\await($this->sxbetPrivateDeleteOrdersV3($this->extend($request, $params)));
        $orders = $this->parse_sxbet_cancel_response($response);
        return $this->safe_dict($orders, 0);
    }

    public function cancel_orders(array $ids, ?string $outcome = null, $params = array()): PromiseInterface {
        return Async\async(self::do_cancel_orders(...))($ids, $outcome, $params);
    }

    private function do_cancel_orders(array $ids, ?string $outcome = null, $params = array()) {
        /**
         * cancels multiple resting maker orders in one $request - v3 cancels are plain api-key-authenticated DELETE requests, no signature involved
         *
         * @see https://docs.sx.bet/api-reference/delete-orders-v3
         *
         * @param {string[]} $ids the order $ids to cancel
         * @param {string} [$outcome] not used by sxbet.cancelOrders
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of [prediction order structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
         */
        $this->check_required_credentials();
        $idsLength = count($ids);
        if ($idsLength === 0) {
            throw new ArgumentsRequired($this->id . ' cancelOrders() requires a non-empty $ids argument');
        }
        // the venue caps one cancel request at maxCancelOrders ids (100, see /metadata/obv3) -
        // chunk larger batches instead of letting the whole request 400
        $chunkSize = $this->safe_integer($this->options, 'cancelOrdersBatchSize', 100);
        $chunkCount = $this->parse_to_int($this->sum($idsLength, $chunkSize - 1) / $chunkSize);
        $result = array();
        for ($c = 0; $c < $chunkCount; $c++) {
            $start = $c * $chunkSize;
            $end = $start . $chunkSize;
            if ($end > $idsLength) {
                $end = $idsLength;
            }
            $orderItems = array();
            for ($i = $start; $i < $end; $i++) {
                $orderItems[] = array( 'orderId' => $ids[$i] );
            }
            $request = array( 'orders' => $orderItems );
            $response = Async\await($this->sxbetPrivateDeleteOrdersV3($this->extend($request, $params)));
            $result = $this->array_concat($result, $this->parse_sxbet_cancel_response($response));
        }
        return $result;
    }

    public function cancel_all_orders(?string $outcome = null, $params = array()): PromiseInterface {
        return Async\async(self::do_cancel_all_orders(...))($outcome, $params);
    }

    private function do_cancel_all_orders(?string $outcome = null, $params = array()) {
        /**
         * cancels every resting maker order of the account, or every order of one fixture via $params->eventId - v3 cancels are plain api-key-authenticated DELETE requests, no signature involved
         *
         * @see https://docs.sx.bet/api-reference/delete-orders-v3-all
         * @see https://docs.sx.bet/api-reference/delete-orders-v3-event
         *
         * @param {string} [$outcome] not used by sxbet.cancelAllOrders
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->eventId] cancels every order across every market of this fixture instead of the account-wide path ($params->sportXeventId is accepted too)
         * @return {array[]} a list of [prediction order structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
         */
        $this->check_required_credentials();
        $eventId = $this->safe_string_2($params, 'eventId', 'sportXeventId');
        $rest = $this->omit($params, array( 'eventId', 'sportXeventId' ));
        $isEventScoped = ($eventId !== null);
        $response = null;
        if ($isEventScoped) {
            // the event route takes eventId in the QUERY string, not the body - sign() urlencodes
            // body-less DELETE params
            $request = array( 'eventId' => $eventId );
            $response = Async\await($this->sxbetPrivateDeleteOrdersV3Event($this->extend($request, $rest)));
        } else {
            $response = Async\await($this->sxbetPrivateDeleteOrdersV3All($rest));
        }
        $result = $this->parse_sxbet_cancel_response($response);
        // both paths paginate their async submission - keep going on the SAME route while more remain
        $hasMore = $this->safe_bool($this->safe_dict($response, 'data', array()), 'hasMore', false);
        $guard = 0;
        while (($hasMore === true) && ($guard < 50)) {
            $nextResponse = null;
            if ($isEventScoped) {
                $nextRequest = array( 'eventId' => $eventId );
                $nextResponse = Async\await($this->sxbetPrivateDeleteOrdersV3Event($this->extend($nextRequest, $rest)));
            } else {
                $nextResponse = Async\await($this->sxbetPrivateDeleteOrdersV3All($rest));
            }
            $result = $this->array_concat($result, $this->parse_sxbet_cancel_response($nextResponse));
            $hasMore = $this->safe_bool($this->safe_dict($nextResponse, 'data', array()), 'hasMore', false);
            $guard = $this->sum($guard, 1);
        }
        return $result;
    }

    public function parse_prediction_order(array $order, ?array $market = null): array {
        /**
         * @ignore
         * parses one raw GET /orders row into a unified prediction $order-> every sx.bet maker $order is a 'buy' of the outcome it bets on (isMakerBettingOutcomeOne selects the side), priced at the maker's own implied probability
         * @param {array} $order the raw sx.bet $order object
         * @param {array} [$market] the outcome object the $order belongs to (resolved from the cache by $outcomeId when omitted)
         * @return {array} a [prediction $order structure](https://docs.ccxt.com/#/?id=prediction-$order-structure)
         */
        //
        //     {
        //         "id": "0x112a4f19f20395aefcdb5d26f3f8aab0d96b1aff7ce346c0bfb13d9490340cdf",
        //         "marketHash": "0xbf06c6379c922d8118612d1d7493b20f6df6929437fbf6022904327f9516a2eb",
        //         "userAddress": "0xbcc6D643e4159A75ED1dB4e13330230B82F2AEe5",
        //         "wallet": "0x4361123dbdc1D812fdf7D27045aF358C9C8AA70A",
        //         "isBettingOutcomeOne": true,
        //         "percentageOdds": "40000000000000000000",
        //         "totalBetSize": "3000000",
        //         "remainingSize": "3000000",
        //         "expiry": null,
        //         "status": "ACTIVE",
        //         "inactiveReason": null,
        //         "eventId": "L12003787",
        //         "createdAt": "2026-07-31T18:45:42.636Z",
        //         "updatedAt": "2026-07-31T18:45:42.838Z"
        //     }
        //
        $orderId = $this->safe_string_2($order, 'id', 'orderId');
        $marketHash = $this->safe_string($order, 'marketHash', '');
        $isBettingOutcomeOne = $this->safe_bool($order, 'isBettingOutcomeOne', true);
        $outcomeId = ($isBettingOutcomeOne) ? $marketHash : ($marketHash . '-2');
        $outcomeObj = $this->safe_outcome($outcomeId, $market);
        $oneDenom = '100000000000000000000';
        $usdcDecimals = '1000000';
        $percentageOdds = $this->safe_string($order, 'percentageOdds');
        $price = ($percentageOdds !== null) ? $this->parse_number(Precise::string_div($percentageOdds, $oneDenom)) : null;
        $totalBetSize = $this->safe_string($order, 'totalBetSize', '0');
        $remainingSize = $this->safe_string($order, 'remainingSize', $totalBetSize);
        $filledRaw = Precise::string_sub($totalBetSize, $remainingSize);
        $amount = $this->parse_number(Precise::string_div($totalBetSize, $usdcDecimals, 6));
        $filled = $this->parse_number(Precise::string_div($filledRaw, $usdcDecimals, 6));
        $remaining = $this->parse_number(Precise::string_div($remainingSize, $usdcDecimals, 6));
        $orderStatus = $this->safe_string_upper($order, 'status');
        $inactiveReason = $this->safe_string_upper($order, 'inactiveReason');
        $status = 'open';
        if ($orderStatus === 'INACTIVE') {
            // documented inactiveReason enum: FILLED, USER_REQUESTED, EXPIRED, NO_LIQUIDITY,
            // INSUFFICIENT_BALANCE, EVENT_LIFECYCLE, MARKET_HALTED, HEARTBEAT_TIMEOUT, SYSTEM
            if ($inactiveReason === 'FILLED') {
                $status = 'closed';
            } elseif ($inactiveReason === 'EXPIRED') {
                $status = 'expired';
            } else {
                $status = 'canceled';
            }
        }
        $timestamp = $this->parse8601($this->safe_string($order, 'createdAt'));
        return $this->safe_prediction_order(array(
            'id' => $orderId,
            'clientOrderId' => $this->safe_string($order, 'clientOrderId'),
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'lastTradeTimestamp' => $this->parse8601($this->safe_string($order, 'updatedAt')),
            'status' => $status,
            'type' => 'limit',
            'timeInForce' => null,
            'side' => 'buy',
            'price' => $price,
            'average' => null,
            'amount' => $amount,
            'filled' => $filled,
            'remaining' => $remaining,
            'cost' => null,
            'fee' => null,
            'reduceOnly' => null,
            'postOnly' => null,
            'trades' => array(),
            'outcome' => $this->safe_string($outcomeObj, 'outcome'),
            'outcomeId' => $this->safe_string($outcomeObj, 'outcomeId', $outcomeId),
            'label' => $this->safe_string($outcomeObj, 'label'),
            'market' => $this->safe_string($outcomeObj, 'market'),
            'info' => $order,
        ), $outcomeObj);
    }

    public function clamp_sxbet_per_page(?int $limit): ?int {
        /**
         * @ignore
         * clamps a user $limit to the venue's hard perPage ceiling - every v3 listing route rejects perPage above 100, and deeper history is reachable through the nextKey cursor instead
         * @param {int} $limit the user-requested $limit
         * @return {int} the $limit clamped to at most 100
         */
        $maxPerPage = 100;
        if ($limit === null) {
            return null;
        }
        return ($limit > $maxPerPage) ? $maxPerPage : $limit;
    }

    public function fetch_open_orders(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_open_orders(...))($outcome, $since, $limit, $params);
    }

    private function do_fetch_open_orders(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches the account's resting maker orders via the api-key-authenticated GET /orders-v3 (the route is hardcoded to ACTIVE orders and scoped to the key's account)
         *
         * @see https://docs.sx.bet/api-reference/get-orders-v3
         *
         * @param {string} [$outcome] unified $outcome or outcomeId — narrows to that outcome's market
         * @param {int} [$since] applied client-side (the route has no date filter; rows carry createdAt)
         * @param {int} [$limit] the maximum number of orders to return (server-side perPage, max 100, default 50)
         * @param {array} [$params] extra parameters specific to the exchange API endpoint (e.g. eventId, sortBy, sortAsc, nextKey)
         * @return {array[]} a list of [prediction order structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
         */
        $request = array();
        $outcomeObj = null;
        if ($outcome !== null) {
            Async\await($this->load_outcome($outcome));
            $outcomeObj = $this->outcome($outcome);
            $request['marketHash'] = $this->safe_string($outcomeObj['info'], 'marketHash');
        }
        if ($limit !== null) {
            $request['perPage'] = $this->clamp_sxbet_per_page($limit);
        }
        $response = Async\await($this->sxbetPrivateGetOrdersV3($this->extend($request, $params)));
        $data = $this->safe_dict($response, 'data', array());
        $rawOrders = $this->safe_list($data, 'orders', array());
        return $this->parse_prediction_orders($rawOrders, $outcomeObj, $since, $limit);
    }

    public function fetch_orders(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_orders(...))($outcome, $since, $limit, $params);
    }

    private function do_fetch_orders(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches the account's maker orders. sx.bet's GET /orders-v3 listing is hardcoded to ACTIVE orders — filled/cancelled/expired orders leave the listing permanently (their history is only reconstructable from fills), so this returns the same set that fetchOpenOrders returns
         *
         * @see https://docs.sx.bet/api-reference/get-orders-v3
         *
         * @param {string} [$outcome] unified $outcome or outcomeId — narrows to that outcome's market
         * @param {int} [$since] applied client-side (the route has no date filter; rows carry createdAt)
         * @param {int} [$limit] the maximum number of orders to return (server-side perPage, max 100, default 50)
         * @param {array} [$params] extra parameters specific to the exchange API endpoint (e.g. eventId, sortBy, sortAsc, nextKey)
         * @return {array[]} a list of [prediction order structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
         */
        return Async\await($this->fetch_open_orders($outcome, $since, $limit, $params));
    }

    public function fetch_order(?string $id, ?string $outcome = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_order(...))($id, $outcome, $params);
    }

    private function do_fetch_order(?string $id, ?string $outcome = null, $params = array()) {
        /**
         * fetches a single maker order by its order hash - unlike the listing, GET /orders-v3/{orderId} also serves filled, cancelled and expired orders while they still exist. a missing or foreign $id 404s with 'Order not found', surfaced through handleErrors's OrderNotFound mapping
         *
         * @see https://docs.sx.bet/api-reference/get-order-v3
         *
         * @param {string} $id the order hash
         * @param {string} [$outcome] unified $outcome or outcomeId (labelling hint only, the $request needs just the $id)
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a [prediction order structure](https://docs.ccxt.com/#/?$id=prediction-order-structure)
         */
        $this->check_required_credentials();
        if ($id === null) {
            throw new ArgumentsRequired($this->id . ' fetchOrder() requires an $id argument');
        }
        $outcomeObj = null;
        if ($outcome !== null) {
            Async\await($this->load_outcome($outcome));
            $outcomeObj = $this->outcome($outcome);
        }
        $request = array( 'orderId' => $id );
        $response = Async\await($this->sxbetPrivateGetOrdersV3OrderId($this->extend($request, $params)));
        $data = $this->safe_dict($response, 'data', array());
        $row = $this->safe_dict($data, 'order', $data);
        return $this->parse_prediction_order($row, $outcomeObj);
    }

    public function fetch_trades(?string $outcome, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_trades(...))($outcome, $since, $limit, $params);
    }

    private function do_fetch_trades(?string $outcome, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches the public trade tape of one outcome's market — every bettor's settled and in-flight bets on that market. the venue requires the $trades listing to be scoped, so the $outcome argument is mandatory
         *
         * @see https://docs.sx.bet/api-reference/get-$trades-v3-public
         *
         * @param {string} $outcome unified $outcome or outcomeId
         * @param {int} [$since] timestamp in ms of the earliest trade to return — applied client-side over the newest page (the public tape serves newest-first and has no date filter; older pages are reachable through $params->nextKey)
         * @param {int} [$limit] the maximum number of $trades to return (server-side perPage, max 100, default 50)
         * @param {array} [$params] extra parameters specific to the exchange API endpoint (e.g. eventId, nextKey)
         * @return {array[]} a list of [prediction trade structures](https://docs.ccxt.com/#/?id=prediction-trade-structure)
         */
        if ($outcome === null) {
            throw new ArgumentsRequired($this->id . ' fetchTrades() requires an $outcome argument - the venue requires the $trades listing to be scoped');
        }
        Async\await($this->load_outcome($outcome));
        $outcomeObj = $this->outcome($outcome);
        $request = array( 'marketHash' => $this->safe_string($outcomeObj['info'], 'marketHash') );
        if ($limit !== null) {
            $request['perPage'] = $this->clamp_sxbet_per_page($limit);
        }
        $response = Async\await($this->sxbetPublicGetTradesV3Public($this->extend($request, $params)));
        $data = $this->safe_dict($response, 'data', array());
        $rawTrades = $this->safe_list($data, 'trades', array());
        $trades = array();
        $rawTradesLength = count($rawTrades);
        for ($i = 0; $i < $rawTradesLength; $i++) {
            $trades[] = $this->parse_sxbet_v3_public_trade($rawTrades[$i]);
        }
        // the venue serves the tape newest-first - the unified contract is ascending by timestamp
        $trades = $this->sort_by($trades, 'timestamp');
        $sym = $this->safe_string($outcomeObj, 'outcome');
        return $this->filter_by_value_since_limit($trades, 'outcome', $sym, $since, $limit, 'timestamp', true);
    }

    public function fetch_my_trades(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_my_trades(...))($outcome, $since, $limit, $params);
    }

    private function do_fetch_my_trades(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches the account's fills (matched legs of its own orders, both taker and maker side) via the api-key-authenticated GET /fills-v3
         *
         * @see https://docs.sx.bet/api-reference/get-fills-v3
         *
         * @param {string} [$outcome] unified $outcome or outcomeId — narrows to that outcome's market and drops the opposite side's legs
         * @param {int} [$since] timestamp in ms of the earliest fill to fetch (server-side startDate)
         * @param {int} [$limit] the maximum number of fills to return (server-side perPage, max 100, default 50)
         * @param {array} [$params] extra parameters specific to the exchange API endpoint (e.g. tradeId, orderId, endDate, sortAsc, nextKey)
         * @return {array[]} a list of [prediction trade structures](https://docs.ccxt.com/#/?id=prediction-trade-structure)
         */
        $this->check_required_credentials();
        $request = array();
        $outcomeObj = null;
        if ($outcome !== null) {
            Async\await($this->load_outcome($outcome));
            $outcomeObj = $this->outcome($outcome);
        }
        if ($since !== null) {
            $request['startDate'] = $this->iso8601($since);
        }
        if (($limit !== null) && ($outcome === null)) {
            // with an outcome filter the rows are narrowed client-side - a server-side page
            // size would truncate the page before the filter and under-fill the result
            $request['perPage'] = $this->clamp_sxbet_per_page($limit);
        }
        $response = Async\await($this->sxbetPrivateGetFillsV3($this->extend($request, $params)));
        $data = $this->safe_dict($response, 'data', array());
        $rawFills = $this->safe_list($data, 'fills', array());
        $trades = array();
        $rawFillsLength = count($rawFills);
        for ($i = 0; $i < $rawFillsLength; $i++) {
            $trades[] = $this->parse_sxbet_v3_fill($rawFills[$i]);
        }
        $trades = $this->sort_by($trades, 'timestamp');
        $sym = ($outcomeObj !== null) ? $this->safe_string($outcomeObj, 'outcome') : null;
        return $this->filter_by_value_since_limit($trades, 'outcome', $sym, $since, $limit, 'timestamp', true);
    }

    public function parse_sxbet_v3_fill(array $fill, ?array $market = null): array {
        /**
         * @ignore
         * parses one GET /fills-v3 row into a unified trade - each $fill is one maker/taker match of the wallet's own order
         * @param {array} $fill the raw $fill row
         * @param {array} [$market] the outcome object labelling hint
         * @return {array} a [prediction trade structure](https://docs.ccxt.com/#/?id=prediction-trade-structure)
         */
        //
        //     {
        //         "id": "0xec8e...:0x02d2...:0x1fec...",
        //         "matchId": "0xec8e...", "orderId": "0x02d2...", "tradeId": "0xac6b...",
        //         "marketHash": "0x1fec...", "isParlay": false,
        //         "userAddress": "0xbcc6...", "wallet": "0x4361...",
        //         "fillAmount": "333334", "fillOdds": "40000000000000000000",
        //         "returnAmount": "833335", "isBettingOutcomeOne": false,
        //         "isMaker": false, "status": "LOCKED", "txHash": "0x6430...",
        //         "ceRefundAmount": "0", "ceRefundFeeAmount": "0",
        //         "usedBetCredits": false, "createdAt": "2026-07-31T18:47:09.586Z",
        //         "updatedAt": "2026-07-31T18:47:12.837Z", "settlement": null
        //     }
        //
        $marketHash = $this->safe_string($fill, 'marketHash', '');
        $isBettingOutcomeOne = $this->safe_bool($fill, 'isBettingOutcomeOne', true);
        $outcomeId = ($isBettingOutcomeOne) ? $marketHash : ($marketHash . '-2');
        $outcomeObj = $this->safe_outcome($outcomeId, $market);
        $oneDenom = '100000000000000000000';
        $usdcDecimals = '1000000';
        $fillOdds = $this->safe_string($fill, 'fillOdds');
        $price = ($fillOdds !== null) ? $this->parse_number(Precise::string_div($fillOdds, $oneDenom)) : null;
        $fillAmount = $this->safe_string($fill, 'fillAmount', '0');
        $amount = $this->parse_number(Precise::string_div($fillAmount, $usdcDecimals, 6));
        $timestamp = $this->parse8601($this->safe_string($fill, 'createdAt'));
        // isMaker: true when the account's order was the resting one - absent on older rows
        $isMaker = $this->safe_bool($fill, 'isMaker');
        $takerOrMaker = null;
        if ($isMaker !== null) {
            $takerOrMaker = ($isMaker === true) ? 'maker' : 'taker';
        }
        return $this->safe_prediction_trade(array(
            'id' => $this->safe_string($fill, 'id'),
            'info' => $fill,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'outcome' => $this->safe_string($outcomeObj, 'outcome'),
            'outcomeId' => $this->safe_string($outcomeObj, 'outcomeId', $outcomeId),
            'label' => $this->safe_string($outcomeObj, 'label'),
            'market' => $this->safe_string($outcomeObj, 'market'),
            'order' => $this->safe_string($fill, 'orderId'),
            'type' => null,
            'side' => 'buy',
            'takerOrMaker' => $takerOrMaker,
            'price' => $price,
            'amount' => $amount,
            'cost' => $amount,
            'fee' => null,
        ), $market);
    }

    public function fetch_balance($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_balance(...))($params);
    }

    private function do_fetch_balance($params = array()) {
        /**
         * fetches the account's order-spendable proxy balance from GET /user/balance-v3 - v3 trading capital sits inside the $obv3 proxy wallet (funded via approve()), and GTC posting is checked against availableAmount. $free is the spendable availableAmount, $used the escrowedAmount locked behind open bets
         *
         * @see https://docs.sx.bet/api-reference/get-user-balance-v3
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a [balance structure](https://docs.ccxt.com/#/?id=balance-structure)
         */
        $obv3 = Async\await($this->load_sx_obv3_metadata());
        $activeAsset = $this->safe_dict($obv3, 'activeAsset', array());
        $usdcAddress = $this->safe_string_lower($activeAsset, 'baseToken', '');
        $response = Async\await($this->sxbetPrivateGetUserBalanceV3($params));
        //
        //     { "status": "success", "data": { "balances": [ {
        //         "userAddress": "0xC3f4...", "wallet": "0x19D1...",
        //         "tokenAddress": "0x1BC6...", "escrowAddress": "0x0Db3...",
        //         "availableAmount": "0", "pendingAvailableAmount": "0",
        //         "escrowedAmount": "0", "pendingEscrowAmount": "0" } ] } }
        //
        $data = $this->safe_dict($response, 'data', array());
        $balances = $this->safe_list($data, 'balances', array());
        $result = array( 'info' => $response );
        $usdcDecimals = '1000000';
        $balancesLength = count($balances);
        for ($i = 0; $i < $balancesLength; $i++) {
            $row = $balances[$i];
            $tokenAddress = $this->safe_string_lower($row, 'tokenAddress', '');
            // every sxbet market is denominated in the active base token, surfaced under 'USDC';
            // rows of any other token keep their contract address for the code
            $code = $this->safe_string($row, 'tokenAddress', '');
            if ($tokenAddress === $usdcAddress) {
                $code = 'USDC';
            }
            $free = Precise::string_div($this->safe_string($row, 'availableAmount', '0'), $usdcDecimals, 6);
            $used = Precise::string_div($this->safe_string($row, 'escrowedAmount', '0'), $usdcDecimals, 6);
            $result[$code] = array(
                'free' => $this->parse_number($free),
                'used' => $this->parse_number($used),
                'total' => $this->parse_number(Precise::string_add($free, $used)),
            );
        }
        return $this->safe_balance($result);
    }

    public function fetch_positions(?array $outcomes = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_positions(...))($outcomes, $params);
    }

    private function do_fetch_positions(?array $outcomes = null, $params = array()) {
        /**
         * fetches the account's open positions from the venue's per-market aggregates (GET /positions-v3, MATCHED and LOCKED bets by default; override with $params->status - the enum is MATCHED, LOCKED, SETTLED, FAILED, and pnl is populated only when the filter is exclusively SETTLED). contracts is the total stake at risk, entryPrice the blended implied probability of the market's best-case outcome
         *
         * @see https://docs.sx.bet/api-reference/get-positions-v3
         *
         * @param {string[]} [$outcomes] filter by unified $outcomes or outcomeIds
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of [prediction position structures](https://docs.ccxt.com/#/?id=prediction-position-structure)
         */
        $this->check_required_credentials();
        // copy to a plain list so the transpilers and the strict null checks see one shape
        $outcomesList = ($outcomes === null) ? array() : $outcomes;
        $outcomesLength = count($outcomesList);
        $wantedMarkets = array();
        if ($outcomesLength > 0) {
            Async\await($this->load_outcomes($outcomesList));
            for ($i = 0; $i < $outcomesLength; $i++) {
                $outcomeObj = $this->outcome($outcomesList[$i]);
                $hash = $this->safe_string($outcomeObj['info'], 'marketHash', '');
                $wantedMarkets[$hash] = true;
            }
        }
        // open exposure lives in MATCHED and LOCKED bets - the venue requires an explicit status
        // list drawn from MATCHED, LOCKED, SETTLED, FAILED
        $request = array( 'status' => $this->safe_string($params, 'status', 'MATCHED,LOCKED') );
        $rest = $this->omit($params, array( 'status' ));
        $response = Async\await($this->sxbetPrivateGetPositionsV3($this->extend($request, $rest)));
        $data = $this->safe_dict($response, 'data', array());
        $rawPositions = $this->safe_list($data, 'positions', array());
        $result = array();
        $rawPositionsLength = count($rawPositions);
        for ($i = 0; $i < $rawPositionsLength; $i++) {
            $raw = $rawPositions[$i];
            $marketHash = $this->safe_string($raw, 'marketHash', '');
            if ($outcomesLength > 0) {
                if ($this->safe_bool($wantedMarkets, $marketHash) === null) {
                    continue;
                }
            }
            $result[] = $this->parse_sxbet_v3_position($raw);
        }
        return $result;
    }

    public function parse_sxbet_v3_position(array $raw): array {
        /**
         * @ignore
         * parses one GET /positions-v3 row (per-market aggregate) into a unified position on the market's best-case outcome
         * @param {array} $raw the $raw position row
         * @return {array} a [prediction position structure](https://docs.ccxt.com/#/?id=prediction-position-structure)
         */
        //
        //     {
        //         "marketHash": "0x8120...", "market": {...},
        //         "totalStake": "300000000", "maxWin": "200000000", "maxLoss": "-100000000",
        //         "isOutcomeOneMaxWin": true,
        //         "odds": {"outcomeOne": "40000000000000000000", "outcomeTwo": "50000000000000000000"},
        //         "pnl": null, "tradeCount": 2,
        //         "betTime": "2026-03-13T21:14:02.118Z", "updatedAt": "2026-03-13T22:03:41.502Z"
        //     }
        //
        $marketHash = $this->safe_string($raw, 'marketHash', '');
        $isOutcomeOneMaxWin = $this->safe_bool($raw, 'isOutcomeOneMaxWin', true);
        $outcomeId = ($isOutcomeOneMaxWin) ? $marketHash : ($marketHash . '-2');
        $outcomeObj = $this->safe_outcome($outcomeId);
        $oneDenom = '100000000000000000000';
        $usdcDecimals = '1000000';
        $odds = $this->safe_dict($raw, 'odds', array());
        $ownOdds = ($isOutcomeOneMaxWin) ? $this->safe_string($odds, 'outcomeOne') : $this->safe_string($odds, 'outcomeTwo');
        $entryPrice = ($ownOdds !== null) ? $this->parse_number(Precise::string_div($ownOdds, $oneDenom)) : null;
        $totalStake = $this->safe_string($raw, 'totalStake', '0');
        $pnl = $this->safe_string($raw, 'pnl');
        $timestamp = $this->parse8601($this->safe_string($raw, 'betTime'));
        return $this->safe_prediction_position(array(
            'outcome' => $this->safe_string($outcomeObj, 'outcome'),
            'outcomeId' => $this->safe_string($outcomeObj, 'outcomeId', $outcomeId),
            'label' => $this->safe_string($outcomeObj, 'label'),
            'market' => $this->safe_string($outcomeObj, 'market'),
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'lastUpdateTimestamp' => $this->parse8601($this->safe_string($raw, 'updatedAt')),
            'contracts' => $this->parse_number(Precise::string_div($totalStake, $usdcDecimals, 6)),
            'entryPrice' => $entryPrice,
            'markPrice' => null,
            'unrealizedPnl' => null,
            'realizedPnl' => ($pnl !== null) ? $this->parse_number(Precise::string_div($pnl, $usdcDecimals, 6)) : null,
            'side' => 'long',
            'info' => $raw,
        ));
    }

    public function fetch_settlements(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_settlements(...))($outcome, $since, $limit, $params);
    }

    private function do_fetch_settlements(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches the account's settled bets — each settled GET /trades-v3 row becomes one $settlement with the resolved winner, the payout (stake / odds when won, the stake back when the market voided, zero when lost) and the realized pnl
         *
         * @see https://docs.sx.bet/api-reference/get-trades-v3
         *
         * @param {string} [$outcome] filter to a single unified $outcome or outcomeId
         * @param {int} [$since] timestamp in ms of the earliest $settlement to fetch (server-side startDate on the bet time)
         * @param {int} [$limit] the maximum number of settlements to fetch (server-side perPage, max 100, default 50)
         * @param {array} [$params] extra parameters specific to the exchange API endpoint (e.g. eventId, endDate, sortAsc, nextKey)
         * @return {array[]} a list of prediction $settlement structures
         */
        $this->check_required_credentials();
        $request = array( 'status' => 'SETTLED' );
        $wantedOutcomeId = null;
        if ($outcome !== null) {
            Async\await($this->load_outcome($outcome));
            $outcomeObj = $this->outcome($outcome);
            $request['marketHash'] = $this->safe_string($outcomeObj['info'], 'marketHash', '');
            $wantedOutcomeId = $this->safe_string($outcomeObj, 'outcomeId');
        }
        if ($since !== null) {
            $request['startDate'] = $this->iso8601($since);
        }
        if (($limit !== null) && ($outcome === null)) {
            // the outcome scope narrows rows client-side (the venue filter is per market, not
            // per side) - a server-side page size would under-fill the filtered result
            $request['perPage'] = $this->clamp_sxbet_per_page($limit);
        }
        $response = Async\await($this->sxbetPrivateGetTradesV3($this->extend($request, $params)));
        $data = $this->safe_dict($response, 'data', array());
        $rawTrades = $this->safe_list($data, 'trades', array());
        $result = array();
        $rawTradesLength = count($rawTrades);
        for ($i = 0; $i < $rawTradesLength; $i++) {
            $settlement = $this->parse_settlement($rawTrades[$i]);
            if (($wantedOutcomeId === null) || ($this->safe_string($settlement, 'outcomeId') === $wantedOutcomeId)) {
                $result[] = $settlement;
            }
        }
        return $result;
    }

    public function parse_settlement(array $trade, ?array $market = null): mixed {
        /**
         * @ignore
         * parses one settled GET /trades-v3 row into the unified prediction $settlement shape. the raw `outcome` field carries the $winner, 1 or 2, with 0 for a voided $market, and the full $payout of a winning bet is $stake / odds (the implied probability the bettor received)
         * @param {array} $trade the raw settled sx.bet $trade
         * @param {array} [$market] a resolved outcome/market hint
         * @return {array} a prediction $settlement structure
         */
        //
        //     TradeV3 row with a settlement sub-object:
        //     {
        //         "tradeId": "0xac6b...", "marketHash": "0x1fec...",
        //         "isBettingOutcomeOne": false, "totalStake": "1000000", "totalReturn": "2500000",
        //         "weightedAverageOdds": "40000000000000000000", "status": "SETTLED",
        //         "betTime": "2026-07-31T18:47:09.577Z",
        //         "settlement": { "outcome": 2, "settleReturnAmount": "2500000",
        //                         "settleFeeAmount": "0", "settleCeRefundAmount": "0",
        //                         "settleDate": "2026-08-01T00:10:00.000Z" }
        //     }
        //
        $marketHash = $this->safe_string($trade, 'marketHash', '');
        $isBettingOutcomeOne = $this->safe_bool($trade, 'isBettingOutcomeOne', true);
        $outcomeId = ($isBettingOutcomeOne) ? $marketHash : ($marketHash . '-2');
        $outcomeObj = $this->safe_outcome($outcomeId, $market);
        $settlement = $this->safe_dict($trade, 'settlement', array());
        $winner = $this->safe_integer($settlement, 'outcome');
        $isVoid = ($winner === 0);
        $heldNumber = ($isBettingOutcomeOne) ? 1 : 2;
        $won = null;
        if (($winner !== null) && !$isVoid) {
            $won = ($winner === $heldNumber);
        }
        $usdcDecimals = '1000000';
        $stake = Precise::string_div($this->safe_string($trade, 'totalStake', '0'), $usdcDecimals, 6);
        $payout = Precise::string_div($this->safe_string($settlement, 'settleReturnAmount', '0'), $usdcDecimals, 6);
        $pnl = Precise::string_sub($payout, $stake);
        // resolve the winning side's human label through the cached market when available
        $resultLabel = null;
        if ($isVoid) {
            $resultLabel = 'VOID';
        } elseif ($winner !== null) {
            $info = $this->safe_dict($outcomeObj, 'info', array());
            $labelKey = ($winner === 1) ? 'outcomeOneName' : 'outcomeTwoName';
            $resultLabel = $this->safe_string($info, $labelKey, $this->number_to_string($winner));
        }
        $timestamp = $this->parse8601($this->safe_string($settlement, 'settleDate'));
        $settlePrice = null;
        if ($won !== null) {
            $settlePrice = ($won === true) ? 1 : 0;
        }
        return array(
            'info' => $trade,
            'id' => $this->safe_string($trade, 'tradeId'),
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'outcome' => $this->safe_string($outcomeObj, 'outcome', $outcomeId),
            'outcomeId' => $this->safe_string($outcomeObj, 'outcomeId', $outcomeId),
            'market' => $this->safe_string($outcomeObj, 'market'),
            'event' => null,
            'result' => $resultLabel,
            'won' => $won,
            'amount' => $this->parse_number($stake),
            'price' => $settlePrice,
            'cost' => $this->parse_number($stake),
            'payout' => $this->parse_number($payout),
            'pnl' => $this->parse_number($pnl),
        );
    }

    public function fetch_sxbet_book_snapshot(?string $marketHash): PromiseInterface {
        return Async\async(self::do_fetch_sxbet_book_snapshot(...))($marketHash);
    }

    private function do_fetch_sxbet_book_snapshot(?string $marketHash) {
        /**
         * @ignore
         * fetches the v3 aggregated order book snapshot of one market (array(outcomeOne, outcomeTwo, version) price levels)
         *
         * @see https://docs.sx.bet/api-reference/get-orderbook-snapshot
         *
         * @param {string} $marketHash the market hash
         * @return {array} the raw snapshot data
         */
        $request = array( 'marketHash' => $marketHash );
        $response = Async\await($this->sxbetPublicGetOrderbookV3Snapshot($request));
        return $this->safe_dict($response, 'data', array());
    }

    public function fetch_ticker(?string $outcome, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_ticker(...))($outcome, $params);
    }

    private function do_fetch_ticker(?string $outcome, $params = array()) {
        /**
         * fetches the current best resting odds for a single sx.bet $outcome-> sx.bet is a peer-to-peer odds book (no matched-trade tape or candles), so bid/ask are the best (highest) percentageOdds resting on this outcome's own side and its mirror (1 - best percentageOdds resting on the opposite $outcome)
         *
         * @see https://docs.sx.bet/api-reference/get-orderbook-$snapshot
         *
         * @param {string} $outcome unified $outcome handle or outcomeId ($marketHash or $marketHash . '-2')
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a [prediction ticker structure](https://docs.ccxt.com/#/?id=prediction-ticker-structure)
         */
        Async\await($this->load_outcome($outcome));
        $outcomeObj = $this->outcome($outcome);
        $marketHash = $this->safe_string($outcomeObj['info'], 'marketHash');
        // the book snapshot is public and carries the same top of book - the batched best-odds
        // route needs an apiKey, so it only pays off for the multi-market path
        $snapshot = Async\await($this->fetch_sxbet_book_snapshot($marketHash));
        $raw = $this->parse_sxbet_snapshot_best_odds($snapshot);
        return $this->parse_prediction_ticker($raw, $outcomeObj);
    }

    public function fetch_sxbet_best_odds(array $marketHashes, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_sxbet_best_odds(...))($marketHashes, $params);
    }

    private function do_fetch_sxbet_best_odds(array $marketHashes, $params = array()) {
        /**
         * @ignore
         * fetches the best resting level of both sides for a set of markets in one $request
         *
         * @see https://docs.sx.bet/api-reference/get-best-odds-v3
         *
         * @param {string[]} $marketHashes the market hashes to query, at most 100 per call
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} the raw bestOdds rows (array(marketHash, outcomeOne, outcomeTwo))
         */
        $request = array( 'marketHashes' => implode(',', $marketHashes) );
        $response = Async\await($this->sxbetPrivateGetOrdersV3OddsBest($this->extend($request, $params)));
        $data = $this->safe_dict($response, 'data', array());
        return $this->safe_list($data, 'bestOdds', array());
    }

    public function parse_sxbet_snapshot_best_odds(array $snapshot): array {
        /**
         * @ignore
         * reduces a v3 book $snapshot to the legacy best-odds shape the ticker parser consumes (array(marketHash, outcomeOne => {percentageOdds}, outcomeTwo => {percentageOdds}))
         * @param {array} $snapshot the raw $snapshot data
         * @return {array} the best-odds shaped dict
         */
        // levels arrive sorted best-first; the best level's odds mirror the v2 best-odds fields
        $oneLevels = $this->safe_list($snapshot, 'outcomeOne', array());
        $twoLevels = $this->safe_list($snapshot, 'outcomeTwo', array());
        $bestOne = $this->safe_dict($oneLevels, 0, array());
        $bestTwo = $this->safe_dict($twoLevels, 0, array());
        return array(
            'marketHash' => $this->safe_string($snapshot, 'marketHash'),
            'outcomeOne' => array( 'percentageOdds' => $this->safe_string($bestOne, 'percentageOdds') ),
            'outcomeTwo' => array( 'percentageOdds' => $this->safe_string($bestTwo, 'percentageOdds') ),
        );
    }

    public function fetch_tickers(?array $outcomes = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_tickers(...))($outcomes, $params);
    }

    private function do_fetch_tickers(?array $outcomes = null, $params = array()) {
        /**
         * fetches the current best resting odds for multiple sx.bet $outcomes, one book $snapshot per market
         *
         * @see https://docs.sx.bet/api-reference/get-orderbook-$snapshot
         *
         * @param {string[]} $outcomes unified $outcomes - required => sx.bet has thousands of markets and no endpoint returning all of them at once
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a dictionary of [prediction ticker structures](https://docs.ccxt.com/#/?id=prediction-ticker-structure) indexed by outcome
         */
        if ($outcomes === null) {
            throw new ArgumentsRequired($this->id . ' fetchTickers() requires an $outcomes argument - sx.bet has thousands of markets and serves best odds per market list');
        }
        $outcomesList = $outcomes;
        $outcomesLength = count($outcomesList);
        $hashesOrder = array();
        $seenHashes = array();
        for ($i = 0; $i < $outcomesLength; $i++) {
            Async\await($this->load_outcome($outcomesList[$i]));
            $outcomeObj = $this->outcome($outcomesList[$i]);
            $marketHash = $this->safe_string($outcomeObj['info'], 'marketHash', '');
            if ($this->safe_bool($seenHashes, $marketHash) === null) {
                $seenHashes[$marketHash] = true;
                $hashesOrder[] = $marketHash;
            }
        }
        // both outcomes of a market share one row, and the venue takes at most 100 hashes per call.
        // the batched route is apiKey-authenticated, so fall back to the public per-market
        // snapshots when the instance carries no credentials
        $rowsByHash = array();
        $hashesLength = count($hashesOrder);
        $hasApiKey = !$this->is_empty_string($this->apiKey);
        if (!$hasApiKey) {
            for ($i = 0; $i < $hashesLength; $i++) {
                $marketHash = $hashesOrder[$i];
                $snapshot = Async\await($this->fetch_sxbet_book_snapshot($marketHash));
                $rowsByHash[$marketHash] = $this->parse_sxbet_snapshot_best_odds($snapshot);
            }
            return $this->parse_sxbet_tickers_by_hash($outcomesList, $rowsByHash);
        }
        $chunkSize = $this->safe_integer($this->options, 'bestOddsBatchSize', 100);
        $chunkCount = $this->parse_to_int($this->sum($hashesLength, $chunkSize - 1) / $chunkSize);
        for ($c = 0; $c < $chunkCount; $c++) {
            $start = $c * $chunkSize;
            $end = $start . $chunkSize;
            if ($end > $hashesLength) {
                $end = $hashesLength;
            }
            $chunk = $this->array_slice($hashesOrder, $start, $end);
            $rows = Async\await($this->fetch_sxbet_best_odds($chunk, $params));
            $rowsLength = count($rows);
            for ($j = 0; $j < $rowsLength; $j++) {
                $row = $rows[$j];
                $rowHash = $this->safe_string($row, 'marketHash');
                if ($rowHash !== null) {
                    $rowsByHash[$rowHash] = $row;
                }
            }
        }
        return $this->parse_sxbet_tickers_by_hash($outcomesList, $rowsByHash);
    }

    public function parse_sxbet_tickers_by_hash(array $outcomesList, array $rowsByHash): array {
        /**
         * @ignore
         * assembles the unified tickers dict from best-odds shaped rows keyed by market hash
         * @param {string[]} $outcomesList the requested unified outcomes
         * @param {array} $rowsByHash best-odds rows indexed by market hash
         * @return {array} a dictionary of [prediction $ticker structures](https://docs.ccxt.com/#/?id=prediction-$ticker-structure) indexed by outcome
         */
        $result = array();
        $outcomesLength = count($outcomesList);
        for ($i = 0; $i < $outcomesLength; $i++) {
            $outcomeObj = $this->outcome($outcomesList[$i]);
            $marketHash = $this->safe_string($outcomeObj['info'], 'marketHash', '');
            $raw = $this->safe_dict($rowsByHash, $marketHash);
            if ($raw === null) {
                continue;
            }
            $ticker = $this->parse_prediction_ticker($raw, $outcomeObj);
            $sym = $this->safe_string($ticker, 'outcome');
            if ($sym !== null) {
                $result[$sym] = $ticker;
            }
        }
        return $result;
    }

    public function parse_prediction_ticker(array $raw, ?array $market = null): array {
        /**
         * @ignore
         * parses one /orders/odds/best entry into a unified ticker for one side of the $market
         * @param {array} $raw one bestOdds entry (array( $marketHash, baseToken, outcomeOne => array( percentageOdds, $updatedAt ), outcomeTwo => array(...) ))
         * @param {array} [$market] the outcome object the ticker belongs to
         * @return {array} a [prediction ticker structure](https://docs.ccxt.com/#/?id=prediction-ticker-structure)
         */
        //
        //     {
        //         "marketHash": "0x48ce0ef287c59fb3bb3ca6deb80de0d5791eb761ea8e16d6f03c8e93ef28d1de",
        //         "baseToken": "0x6629Ce1Cf35Cc1329ebB4F63202F3f197b3F050B",
        //         "outcomeOne": { "percentageOdds": "50250000000000000000", "updatedAt": 1785697831141 },
        //         "outcomeTwo": { "percentageOdds": "48000000000000000000", "updatedAt": 1785699649869 }
        //     }
        //
        $marketAny = $market;
        $outcomeObj = $this->safe_outcome($this->safe_string($marketAny, 'outcome'), $marketAny);
        $outcomeId = $this->safe_string($outcomeObj, 'outcomeId');
        $marketHash = $this->safe_string($raw, 'marketHash');
        $isOutcomeOne = ($outcomeId === $marketHash);
        $outcomeOneOdds = $this->safe_dict($raw, 'outcomeOne', array());
        $outcomeTwoOdds = $this->safe_dict($raw, 'outcomeTwo', array());
        $ownOdds = ($isOutcomeOne) ? $outcomeOneOdds : $outcomeTwoOdds;
        $oppositeOdds = ($isOutcomeOne) ? $outcomeTwoOdds : $outcomeOneOdds;
        // percentageOdds is the maker's own implied probability * 1e20 (sx.bet protocol format);
        // the opposite side's best resting maker mirrors into this outcome's ask via 1 - p
        $oneDenom = '100000000000000000000';
        $ownPercentage = $this->safe_string($ownOdds, 'percentageOdds');
        $oppositePercentage = $this->safe_string($oppositeOdds, 'percentageOdds');
        $bid = ($ownPercentage !== null) ? $this->parse_number(Precise::string_div($ownPercentage, $oneDenom)) : null;
        $ask = ($oppositePercentage !== null) ? $this->parse_number(Precise::string_sub('1', Precise::string_div($oppositePercentage, $oneDenom))) : null;
        $updatedAt = $this->safe_integer($ownOdds, 'updatedAt');
        $now = $this->milliseconds();
        $timestamp = ($updatedAt !== null) ? $updatedAt : $now;
        $average = null;
        if (($bid !== null) && ($ask !== null)) {
            $average = $this->parse_number(Precise::string_div(Precise::string_add($this->number_to_string($bid), $this->number_to_string($ask)), '2'));
        }
        return $this->safe_prediction_ticker(array(
            'outcome' => $this->safe_string($outcomeObj, 'outcome'),
            'outcomeId' => $outcomeId,
            'label' => $this->safe_string($outcomeObj, 'label'),
            'market' => $this->safe_string($outcomeObj, 'market'),
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'high' => null,
            'low' => null,
            'bid' => $bid,
            'bidVolume' => null,
            'ask' => $ask,
            'askVolume' => null,
            'open' => null,
            'close' => $bid,
            'last' => $bid,
            'change' => null,
            'percentage' => null,
            'average' => $average,
            'baseVolume' => null,
            'quoteVolume' => null,
            'info' => $raw,
        ), $market);
    }

    public function fetch_order_book(?string $outcome, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_order_book(...))($outcome, $limit, $params);
    }

    private function do_fetch_order_book(?string $outcome, ?int $limit = null, $params = array()) {
        /**
         * fetches the resting maker order book for a single sx.bet $outcome-> bids are maker orders already betting on this $outcome (priced at each maker's own implied probability, sized by their remaining stake); asks mirror the opposite outcome's maker orders (price = 1 - their implied probability, sized by how much a taker could bet against them, per sx.bet's remaining-taker-space formula) — the same YES/NO-style mirrored construction used across this codebase's other binary prediction venues
         *
         * @see https://docs.sx.bet/api-reference/get-orderbook-$snapshot
         *
         * @param {string} $outcome unified $outcome handle or $outcomeId
         * @param {int} [$limit] the maximum number of bids/asks to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a [prediction order book structure](https://docs.ccxt.com/#/?id=prediction-order-book-structure)
         */
        Async\await($this->load_outcome($outcome));
        $outcomeObj = $this->outcome($outcome);
        $marketHash = $this->safe_string($outcomeObj['info'], 'marketHash');
        $outcomeId = $this->safe_string($outcomeObj, 'outcomeId');
        $isOutcomeOne = ($outcomeId === $marketHash);
        $request = array( 'marketHash' => $marketHash );
        $response = Async\await($this->sxbetPublicGetOrderbookV3Snapshot($this->extend($request, $params)));
        $snapshot = $this->safe_dict($response, 'data', array());
        $sides = $this->parse_sxbet_v3_book_sides($snapshot, $isOutcomeOne);
        $sortedBids = $this->safe_list($sides, 'bids', array());
        $sortedAsks = $this->safe_list($sides, 'asks', array());
        if ($limit !== null) {
            $bidsLength = count($sortedBids);
            $bidsEnd = $limit;
            if ($bidsEnd > $bidsLength) {
                $bidsEnd = $bidsLength;
            }
            $sortedBids = $this->array_slice($sortedBids, 0, $bidsEnd);
            $asksLength = count($sortedAsks);
            $asksEnd = $limit;
            if ($asksEnd > $asksLength) {
                $asksEnd = $asksLength;
            }
            $sortedAsks = $this->array_slice($sortedAsks, 0, $asksEnd);
        }
        $timestamp = $this->milliseconds();
        return $this->safe_prediction_order_book(array(
            'outcome' => $this->safe_string($outcomeObj, 'outcome', $outcome),
            'bids' => $sortedBids,
            'asks' => $sortedAsks,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'nonce' => null,
        ), $outcomeObj);
    }

    public function parse_sxbet_v3_book_sides(array $snapshot, bool $isOutcomeOne): array {
        /**
         * @ignore
         * converts a v3 aggregated book $snapshot into sorted [$price, $amount] bid/ask levels for one outcome; shared by fetchOrderBook and the websocket book handler
         * @param {array} $snapshot the raw $snapshot (array(outcomeOne, outcomeTwo) $level lists of array($percentageOdds, $size))
         * @param {boolean} $isOutcomeOne whether the book is built for the market's outcome one
         * @return {array} a dict with sorted 'bids' and 'asks' lists
         */
        $oneDenom = '100000000000000000000';
        $usdcDecimals = '1000000';
        $ownLevels = ($isOutcomeOne) ? $this->safe_list($snapshot, 'outcomeOne', array()) : $this->safe_list($snapshot, 'outcomeTwo', array());
        $oppositeLevels = ($isOutcomeOne) ? $this->safe_list($snapshot, 'outcomeTwo', array()) : $this->safe_list($snapshot, 'outcomeOne', array());
        $bids = array();
        $ownLevelsLength = count($ownLevels);
        for ($i = 0; $i < $ownLevelsLength; $i++) {
            $level = $ownLevels[$i];
            $percentageOdds = $this->safe_string($level, 'percentageOdds');
            $size = $this->safe_string($level, 'size', '0');
            $price = $this->parse_number(Precise::string_div($percentageOdds, $oneDenom));
            $amount = $this->parse_number(Precise::string_div($size, $usdcDecimals, 6));
            $bids[] = array( $price, $amount );
        }
        $asks = array();
        $oppositeLevelsLength = count($oppositeLevels);
        for ($i = 0; $i < $oppositeLevelsLength; $i++) {
            $level = $oppositeLevels[$i];
            $percentageOdds = $this->safe_string($level, 'percentageOdds');
            $size = $this->safe_string($level, 'size', '0');
            // the opposite side's resting stake mirrors into this outcome's ask - the price is the
            // complement, and the takeable amount follows the remaining-taker-space formula
            $price = $this->parse_number(Precise::string_sub('1', Precise::string_div($percentageOdds, $oneDenom)));
            $ratio = Precise::string_div($oneDenom, $percentageOdds, 12);
            $remainingTaker = Precise::string_sub(Precise::string_mul($size, $ratio), $size);
            $amount = $this->parse_number(Precise::string_div($remainingTaker, $usdcDecimals, 6));
            $asks[] = array( $price, $amount );
        }
        return array(
            'bids' => $this->sort_by($bids, 0, true),
            'asks' => $this->sort_by($asks, 0),
        );
    }

    public function request_id(?string $url): float {
        $existing = $this->safe_value($this->options, 'requestId');
        if ($existing === null) {
            $this->options['requestId'] = $this->create_safe_dictionary();
        }
        $options = $this->options['requestId'];
        $previousValue = $this->safe_integer($options, $url, 0);
        $newValue = $this->sum($previousValue, 1);
        if ($url !== null) {
            $this->options['requestId'][$url] = $newValue;
        }
        return $newValue;
    }

    public function register_sxbet_ws_request(float $requestId, string $messageHash, string $subscription) {
        /**
         * @ignore
         * tracks an outgoing Centrifugo connect/subscribe command by its request id, so an error reply can be correlated back to the awaiting future and its registered $subscription hash (see handleCentrifugoFrame)
         * @param {int} $requestId the id sent with the command
         * @param {string} $messageHash the future hash the caller awaits
         * @param {string} $subscription the $subscription hash registered by watch() ('connect' or the channel name)
         */
        $existing = $this->safe_dict($this->options, 'wsPendingRequests');
        if ($existing === null) {
            $this->options['wsPendingRequests'] = $this->create_safe_dictionary();
        }
        $requestIdString = $this->number_to_string($requestId);
        $this->options['wsPendingRequests'][$requestIdString] = array( 'messageHash' => $messageHash, 'subscription' => $subscription );
    }

    public function fetch_sxbet_realtime_token(): PromiseInterface {
        return Async\async(self::do_fetch_sxbet_realtime_token(...))();
    }

    private function do_fetch_sxbet_realtime_token() {
        /**
         * @ignore
         * fetches the short-lived Centrifugo connection token from the relayer; requires the apiKey credential (X-Api-Key header)
         *
         * @see https://docs.sx.bet/developers/realtime-initialization
         *
         * @return {string} the JWT connection token
         */
        if ($this->apiKey === null) {
            throw new ArgumentsRequired($this->id . ' websocket streaming requires the apiKey credential - the realtime token endpoint authenticates with the X-Api-Key header');
        }
        $response = Async\await($this->sxbetPrivateGetUserRealtimeTokenV3ApiKey());
        $data = $this->safe_dict($response, 'data', array());
        return $this->safe_string_2($data, 'token', 'realtimeToken', $this->safe_string($response, 'token'));
    }

    public function connect_sxbet_centrifugo(?string $url): PromiseInterface {
        return Async\async(self::do_connect_sxbet_centrifugo(...))($url);
    }

    private function do_connect_sxbet_centrifugo(?string $url) {
        // Centrifugo requires a token-carrying connect command before any subscribe. This sends it once
        // per connection and resolves when the connect reply arrives (see handleCentrifugoFrame). The base
        // clears client.subscriptions on reconnect, so an absent 'connect' marker means a fresh handshake.
        $client = $this->client($url);
        $connectSent = $this->safe_value($client->subscriptions, 'connect');
        if ($connectSent === null) {
            $this->options['wsConnected'] = false;
            $token = Async\await($this->fetch_sxbet_realtime_token());
            $requestId = $this->request_id($url);
            $this->register_sxbet_ws_request($requestId, 'centrifugoConnected', 'connect');
            $connectMsg = array( 'connect' => array( 'token' => $token, 'name' => 'ccxt' ), 'id' => $requestId );
            return Async\await($this->watch($url, 'centrifugoConnected', $connectMsg, 'connect'));
        }
        if ($this->safe_bool($this->options, 'wsConnected', false)) {
            // the connect reply already arrived on the current connection - safe to subscribe immediately
            return null;
        }
        // connect is in flight, sent by a concurrent subscribe - wait on the shared reply future
        return Async\await($client->future('centrifugoConnected'));
    }

    public function pong(Client $client, mixed $message = null) {
        return Async\async(self::do_pong(...))($client, $message);
    }

    private function do_pong(Client $client, mixed $message = null) {
        // Centrifugo server pings are empty frames; reply with the same empty frame to keep the link alive
        Async\await($client->send('{}'));
    }

    public function subscribe_sxbet_channel(string $messageHash, string $channel): PromiseInterface {
        return Async\async(self::do_subscribe_sxbet_channel(...))($messageHash, $channel);
    }

    private function do_subscribe_sxbet_channel(string $messageHash, string $channel) {
        $url = $this->safe_string($this->urls['api'], 'ws');
        // finish the connect handshake first so the subscribe frame follows the connect reply
        Async\await($this->connect_sxbet_centrifugo($url));
        $requestId = $this->request_id($url);
        $this->register_sxbet_ws_request($requestId, $messageHash, $channel);
        $subscribeMsg = array( 'subscribe' => array( 'channel' => $channel ), 'id' => $requestId );
        return Async\await($this->watch($url, $messageHash, $subscribeMsg, $channel));
    }

    public function handle_message(Client $client, mixed $message) {
        // Centrifugo packs several commands per frame joined by newlines; a multi-command frame fails the
        // base JSON.parse and arrives here in raw-string form, a single command arrives already parsed
        if (gettype($message) === 'string') {
            $lines = explode('\n', $message);
            $linesLength = count($lines);
            for ($i = 0; $i < $linesLength; $i++) {
                $line = $lines[$i];
                if (strlen($line) > 0) {
                    $parsed = json_decode($line, $as_associative_array = true);
                    $this->handle_centrifugo_frame($client, $parsed);
                }
            }
            return;
        }
        $this->handle_centrifugo_frame($client, $message);
    }

    public function handle_centrifugo_frame(Client $client, mixed $msg) {
        $keys = is_array($msg) ? array_keys($msg) : array();
        $keysLength = count($keys);
        if ($keysLength === 0) {
            $this->spawn(array($this, 'pong'), $client, $msg);
            return;
        }
        $requestIdString = $this->safe_string($msg, 'id');
        $pendingRequests = $this->safe_dict($this->options, 'wsPendingRequests', array());
        $pendingEntry = $this->safe_dict($pendingRequests, $requestIdString);
        $errorReply = $this->safe_dict($msg, 'error');
        if ($errorReply !== null) {
            // a rejected connect (bad or expired realtime token) or subscribe (unauthorized or
            // unknown channel) - fail the awaiting future and clear the subscription hash that
            // watch() registered at send time, so the next call re-sends the command instead
            // of waiting forever behind a marker that will never be served
            $error = new ExchangeError($this->id . ' ' . $this->json($msg));
            if ($pendingEntry !== null) {
                $failedHash = $this->safe_string($pendingEntry, 'messageHash');
                $subscription = $this->safe_string($pendingEntry, 'subscription');
                if ($subscription === 'connect') {
                    $this->options['wsConnected'] = false;
                }
                if (($subscription !== null) && (is_array($client->subscriptions) && array_key_exists($subscription ?? '', $client->subscriptions))) {
                    unset($client->subscriptions[$subscription]);
                }
                $this->options['wsPendingRequests'] = $this->omit($pendingRequests, $requestIdString);
                $client->reject($error, $failedHash);
            } else {
                // an error that cannot be correlated to one command fails the whole connection
                $client->reject($error);
            }
            return;
        }
        if ($pendingEntry !== null) {
            // a successful command ack - the tracked request has served its purpose
            $this->options['wsPendingRequests'] = $this->omit($pendingRequests, $requestIdString);
        }
        $connectReply = $this->safe_dict($msg, 'connect');
        if ($connectReply !== null) {
            // connect acknowledged - unblock connectSxbetCentrifugo so channel subscribes can be sent
            $this->options['wsConnected'] = true;
            $client->resolve(true, 'centrifugoConnected');
            return;
        }
        $push = $this->safe_dict($msg, 'push');
        if ($push === null) {
            return;
        }
        $channel = $this->safe_string($push, 'channel');
        if ($channel === null) {
            return;
        }
        $pub = $this->safe_dict($push, 'pub', array());
        $data = $this->safe_value($pub, 'data');
        if ($data === null) {
            return;
        }
        // rows arrive either shaped like one object or like an array of objects - normalize to a list
        $rows = array();
        if ((gettype($data) === 'array' && array_keys($data) === array_keys(array_keys($data)))) {
            $rows = $data;
        } else {
            $rows = array( $data );
        }
        $parts = explode(':', $channel);
        $channelType = $this->safe_string($parts, 0);
        if ($channelType === 'orderbook_v3') {
            $this->handle_order_book($client, $rows);
        } elseif ($channelType === 'best_odds_v3') {
            $this->handle_ticker($client, $rows);
        } elseif ($channelType === 'recent_trades_v3') {
            $this->handle_trades($client, $rows);
        } elseif ($channelType === 'account') {
            // per-account channels: account:orders_v3_#addr / account:fills_v3_#addr
            if (mb_strpos($channel, 'orders_v3') !== false) {
                $this->handle_order($client, $rows);
            } elseif (mb_strpos($channel, 'fills_v3') !== false) {
                $this->handle_my_trade($client, $rows);
            }
        }
    }

    public function watch_order_book(string $outcome, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_watch_order_book(...))($outcome, $limit, $params);
    }

    private function do_watch_order_book(string $outcome, ?int $limit = null, $params = array()) {
        /**
         * streams the order book of an $outcome - the v3 $channel publishes the entire aggregated book on every update with a monotonic version, so each message replaces the held book
         *
         * @see https://docs.sx.bet/api-reference/channel-$orderbook-v3
         *
         * @param {string} $outcome unified $outcome or $outcome token id
         * @param {int} [$limit] the maximum number of order book entries to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a [prediction order book structure](https://docs.ccxt.com/#/?id=prediction-order-book-structure)
         */
        Async\await($this->load_outcome($outcome));
        $outcomeObj = $this->outcome($outcome);
        $sym = $this->safe_string($outcomeObj, 'outcome');
        $marketHash = $this->safe_string($outcomeObj['info'], 'marketHash');
        $channel = 'orderbook_v3:' . $marketHash;
        $messageHash = 'orderbook::' . $sym;
        $url = $this->safe_string($this->urls['api'], 'ws');
        Async\await($this->connect_sxbet_centrifugo($url));
        $client = $this->client($url);
        $isNewSubscription = $this->safe_value($client->subscriptions, $channel) === null;
        if ($this->safe_value($this->orderbooks, $sym) === null) {
            // seed from the REST snapshot so the book is served before the first publication
            $watchedBooks = $this->safe_dict($this->options, 'wsWatchedBooks');
            if ($watchedBooks === null) {
                $this->options['wsWatchedBooks'] = $this->create_safe_dictionary();
            }
            $this->options['wsWatchedBooks'][$sym] = $marketHash;
            $snapshot = Async\await($this->fetch_sxbet_book_snapshot($marketHash));
            $this->apply_sxbet_ws_snapshot($snapshot);
            if ($this->safe_value($this->orderbooks, $sym) === null) {
                $emptyBook = $this->order_book(array());
                $this->orderbooks[$sym] = $emptyBook;
            }
        }
        $requestId = $this->request_id($url);
        $this->register_sxbet_ws_request($requestId, $messageHash, $channel);
        $subscribeMsg = array( 'subscribe' => array( 'channel' => $channel ), 'id' => $requestId );
        $future = $this->watch($url, $messageHash, $subscribeMsg, $channel);
        if ($isNewSubscription) {
            // return the freshly-seeded book immediately instead of blocking until the next publication
            $client->resolve($this->safe_value($this->orderbooks, $sym), $messageHash);
        }
        $orderbook = Async\await($future);
        return $orderbook->limit();
    }

    public function apply_sxbet_ws_snapshot(array $snapshot): array {
        /**
         * @ignore
         * applies one full v3 book publication (array($marketHash, $version, outcomeOne, outcomeTwo)) to every watched outcome of that market, honoring the monotonic $version
         * @param {array} $snapshot the raw book publication
         * @return {string[]} the outcome handles whose books were $refreshed
         */
        $marketHash = $this->safe_string($snapshot, 'marketHash');
        $version = $this->safe_string($snapshot, 'version', '');
        $refreshed = array();
        if ($marketHash === null) {
            return $refreshed;
        }
        $versionsAll = $this->safe_dict($this->options, 'wsBookVersions');
        if ($versionsAll === null) {
            $this->options['wsBookVersions'] = $this->create_safe_dictionary();
        }
        $held = $this->safe_string($this->options['wsBookVersions'], $marketHash, '');
        // versions are fixed-width numeric strings - replace only on a strictly newer publication
        if (($held !== '') && ($version <= $held)) {
            return $refreshed;
        }
        $this->options['wsBookVersions'][$marketHash] = $version;
        $watchedBooks = $this->safe_dict($this->options, 'wsWatchedBooks', array());
        $watchedSyms = is_array($watchedBooks) ? array_keys($watchedBooks) : array();
        $timestamp = $this->milliseconds();
        $watchedSymsLength = count($watchedSyms);
        for ($i = 0; $i < $watchedSymsLength; $i++) {
            $sym = $watchedSyms[$i];
            if ($this->safe_string($watchedBooks, $sym) !== $marketHash) {
                continue;
            }
            $outcomeObj = $this->outcome($sym);
            $outcomeId = $this->safe_string($outcomeObj, 'outcomeId');
            $isOutcomeOne = ($outcomeId === $marketHash);
            $sides = $this->parse_sxbet_v3_book_sides($snapshot, $isOutcomeOne);
            $orderbook = $this->safe_value($this->orderbooks, $sym);
            if ($orderbook === null) {
                $orderbook = $this->order_book(array());
                $this->orderbooks[$sym] = $orderbook;
            }
            $bookSnapshot = array(
                'bids' => $this->safe_list($sides, 'bids', array()),
                'asks' => $this->safe_list($sides, 'asks', array()),
                'timestamp' => $timestamp,
                'datetime' => $this->iso8601($timestamp),
                'nonce' => null,
            );
            $orderbook->reset($bookSnapshot);
            $refreshed[] = $sym;
        }
        return $refreshed;
    }

    public function handle_order_book(Client $client, array $rows) {
        //
        //     {
        //         "marketHash": "0x...",
        //         "version": "00100000000000010015000",
        //         "outcomeOne": [ { "percentageOdds": "40000000000000000000", "size": "1000000" } ],
        //         "outcomeTwo": []
        //     }
        //
        $rowsLength = count($rows);
        for ($i = 0; $i < $rowsLength; $i++) {
            $refreshed = $this->apply_sxbet_ws_snapshot($rows[$i]);
            $refreshedLength = count($refreshed);
            for ($j = 0; $j < $refreshedLength; $j++) {
                $sym = $refreshed[$j];
                $client->resolve($this->safe_value($this->orderbooks, $sym), 'orderbook::' . $sym);
            }
        }
    }

    public function watch_ticker(string $outcome, $params = array()): PromiseInterface {
        return Async\async(self::do_watch_ticker(...))($outcome, $params);
    }

    private function do_watch_ticker(string $outcome, $params = array()) {
        /**
         * streams best-odds updates of an $outcome; the venue $channel is global, entries are filtered down to the requested outcome's market
         *
         * @see https://docs.sx.bet/api-reference/channel-best-odds-v3
         *
         * @param {string} $outcome unified $outcome or $outcome token id
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a [prediction $ticker structure](https://docs.ccxt.com/#/?id=prediction-$ticker-structure)
         */
        Async\await($this->load_outcome($outcome));
        $outcomeObj = $this->outcome($outcome);
        $sym = $this->safe_string($outcomeObj, 'outcome');
        $marketHash = $this->safe_string($outcomeObj['info'], 'marketHash');
        $messageHash = 'ticker::' . $sym;
        $watchedTickers = $this->safe_dict($this->options, 'wsWatchedTickers');
        if ($watchedTickers === null) {
            $this->options['wsWatchedTickers'] = $this->create_safe_dictionary();
        }
        $this->options['wsWatchedTickers'][$sym] = $marketHash;
        $url = $this->safe_string($this->urls['api'], 'ws');
        Async\await($this->connect_sxbet_centrifugo($url));
        $client = $this->client($url);
        $channel = 'best_odds_v3:global';
        $hydrated = false;
        if ($this->safe_value($this->tickers, $sym) === null) {
            // hydrate from the REST snapshot so the first call does not hang until the
            // market's next top-of-book change - the channel is global, so the seed must fire
            // for every newly watched market, not only on a fresh subscription
            $snapshot = Async\await($this->fetch_sxbet_book_snapshot($marketHash));
            $raw = $this->parse_sxbet_snapshot_best_odds($snapshot);
            $ticker = $this->parse_prediction_ticker($raw, $outcomeObj);
            $this->tickers[$sym] = $ticker;
            $hydrated = true;
        }
        $requestId = $this->request_id($url);
        $this->register_sxbet_ws_request($requestId, $messageHash, $channel);
        $subscribeMsg = array( 'subscribe' => array( 'channel' => $channel ), 'id' => $requestId );
        $future = $this->watch($url, $messageHash, $subscribeMsg, $channel);
        if ($hydrated) {
            $client->resolve($this->safe_value($this->tickers, $sym), $messageHash);
        }
        $tickerResult = Async\await($future);
        return $tickerResult;
    }

    public function handle_ticker(Client $client, array $rows) {
        //
        //     {
        //         "marketHash": "0xbf06...16a2eb",
        //         "outcomeOne": { "percentageOdds": "40000000000000000000", "size": "1000000" },
        //         "outcomeTwo": null
        //     }
        //
        $watchedTickers = $this->safe_dict($this->options, 'wsWatchedTickers', array());
        $watchedSyms = is_array($watchedTickers) ? array_keys($watchedTickers) : array();
        $rowsLength = count($rows);
        for ($i = 0; $i < $rowsLength; $i++) {
            $entry = $rows[$i];
            $marketHash = $this->safe_string($entry, 'marketHash');
            if ($marketHash === null) {
                continue;
            }
            // every publication carries BOTH sides (null = no resting liquidity), so the legacy
            // best-odds shape rebuilds directly without any merge cache
            $bestOne = $this->safe_dict($entry, 'outcomeOne', array());
            $bestTwo = $this->safe_dict($entry, 'outcomeTwo', array());
            $raw = array(
                'marketHash' => $marketHash,
                'outcomeOne' => array( 'percentageOdds' => $this->safe_string($bestOne, 'percentageOdds') ),
                'outcomeTwo' => array( 'percentageOdds' => $this->safe_string($bestTwo, 'percentageOdds') ),
            );
            $watchedSymsLength = count($watchedSyms);
            for ($j = 0; $j < $watchedSymsLength; $j++) {
                $sym = $watchedSyms[$j];
                if ($this->safe_string($watchedTickers, $sym) !== $marketHash) {
                    continue;
                }
                $outcomeObj = $this->outcome($sym);
                $ticker = $this->parse_prediction_ticker($raw, $outcomeObj);
                $this->tickers[$sym] = $ticker;
                $client->resolve($ticker, 'ticker::' . $sym);
            }
        }
    }

    public function watch_trades(string $outcome, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_watch_trades(...))($outcome, $since, $limit, $params);
    }

    private function do_watch_trades(string $outcome, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * streams public bets of an $outcome; the venue channel is global, entries are filtered down to the requested $outcome
         *
         * @see https://docs.sx.bet/api-reference/channel-recent-$trades-v3
         *
         * @param {string} $outcome unified $outcome or $outcome token id
         * @param {int} [$since] timestamp in ms of the earliest trade to return
         * @param {int} [$limit] the maximum number of $trades to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of [prediction trade structures](https://docs.ccxt.com/#/?id=prediction-trade-structure)
         */
        Async\await($this->load_outcome($outcome));
        $outcomeObj = $this->outcome($outcome);
        $sym = $this->safe_string($outcomeObj, 'outcome');
        $messageHash = 'trades::' . $sym;
        $trades = Async\await($this->subscribe_sxbet_channel($messageHash, 'recent_trades_v3:global'));
        return $this->filter_by_since_limit($trades, $since, $limit, 'timestamp', true);
    }

    public function parse_sxbet_v3_public_trade(array $trade): array {
        /**
         * @ignore
         * parses one recent_trades_v3 publication (public TradeV3 shape) into a unified $trade
         * @param {array} $trade the raw public $trade row
         * @return {array} a [prediction $trade structure](https://docs.ccxt.com/#/?id=prediction-$trade-structure)
         */
        $marketHash = $this->safe_string($trade, 'marketHash', '');
        $isBettingOutcomeOne = $this->safe_bool($trade, 'isBettingOutcomeOne', true);
        $outcomeId = ($isBettingOutcomeOne) ? $marketHash : ($marketHash . '-2');
        $outcomeObj = $this->safe_outcome($outcomeId);
        $oneDenom = '100000000000000000000';
        $usdcDecimals = '1000000';
        $odds = $this->safe_string($trade, 'weightedAverageOdds');
        $price = ($odds !== null) ? $this->parse_number(Precise::string_div($odds, $oneDenom)) : null;
        $stake = $this->safe_string($trade, 'totalStake', '0');
        $amount = $this->parse_number(Precise::string_div($stake, $usdcDecimals, 6));
        $timestamp = $this->parse8601($this->safe_string($trade, 'betTime'));
        return $this->safe_prediction_trade(array(
            'id' => $this->safe_string($trade, 'tradeId'),
            'info' => $trade,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'outcome' => $this->safe_string($outcomeObj, 'outcome'),
            'outcomeId' => $this->safe_string($outcomeObj, 'outcomeId', $outcomeId),
            'label' => $this->safe_string($outcomeObj, 'label'),
            'market' => $this->safe_string($outcomeObj, 'market'),
            'order' => null,
            'type' => null,
            'side' => 'buy',
            'takerOrMaker' => null,
            'price' => $price,
            'amount' => $amount,
            'cost' => $amount,
            'fee' => null,
        ));
    }

    public function handle_trades(Client $client, array $rows) {
        //
        //     { "trade": { "tradeId": "0xac6b...", "marketHash": "0x1fec...", "isBettingOutcomeOne": true,
        //                  "totalStake": "1000000", "weightedAverageOdds": "40000000000000000000",
        //                  "betTime": "2026-07-31T18:22:41.000Z", ... } }
        //
        $rowsLength = count($rows);
        for ($i = 0; $i < $rowsLength; $i++) {
            $row = $this->safe_dict($rows[$i], 'trade', $rows[$i]);
            $trade = $this->parse_sxbet_v3_public_trade($row);
            $sym = $this->safe_string($trade, 'outcome');
            if ($sym === null) {
                // bet in a market absent from the loaded outcome cache
                continue;
            }
            if ($this->trades === null) {
                $this->trades = $this->create_safe_dictionary();
            }
            if ($this->safe_value($this->trades, $sym) === null) {
                $tradesLimit = $this->safe_integer($this->options, 'tradesLimit', 1000);
                $this->trades[$sym] = new ArrayCache($tradesLimit);
            }
            $stored = $this->trades[$sym];
            $stored->append($trade);
            $client->resolve($stored, 'trades::' . $sym);
        }
    }

    public function watch_my_trades(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_watch_my_trades(...))($outcome, $since, $limit, $params);
    }

    private function do_watch_my_trades(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * streams the authenticated wallet's fills over its per-account v3 $channel
         *
         * @see https://docs.sx.bet/api-reference/channel-fills-v3
         *
         * @param {string} [$outcome] unified $outcome or $outcome token id to narrow the stream down to
         * @param {int} [$since] timestamp in ms of the earliest trade to return
         * @param {int} [$limit] the maximum number of $trades to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of [prediction trade structures](https://docs.ccxt.com/#/?id=prediction-trade-structure)
         */
        if ($this->walletAddress === null) {
            throw new ArgumentsRequired($this->id . ' watchMyTrades() requires a walletAddress');
        }
        $messageHash = 'myTrades';
        if ($outcome !== null) {
            Async\await($this->load_outcome($outcome));
            $outcomeObj = $this->outcome($outcome);
            $sym = $this->safe_string($outcomeObj, 'outcome');
            $messageHash = 'myTrades::' . $sym;
        }
        $channel = 'account:fills_v3_#' . $this->walletAddress;
        $trades = Async\await($this->subscribe_sxbet_channel($messageHash, $channel));
        return $this->filter_by_since_limit($trades, $since, $limit, 'timestamp', true);
    }

    public function handle_my_trade(Client $client, array $rows) {
        //
        //     FillV3 rows - identical to GET /fills-v3
        //
        $rowsLength = count($rows);
        for ($i = 0; $i < $rowsLength; $i++) {
            $row = $this->safe_dict($rows[$i], 'fill', $rows[$i]);
            $trade = $this->parse_sxbet_v3_fill($row);
            $sym = $this->safe_string($trade, 'outcome');
            if ($sym === null) {
                continue;
            }
            if ($this->myTrades === null) {
                $myTradesLimit = $this->safe_integer($this->options, 'myTradesLimit', 1000);
                $this->myTrades = new ArrayCacheByOutcomeById($myTradesLimit);
            }
            $stored = $this->myTrades;
            $stored->append($trade);
            $client->resolve($stored, 'myTrades');
            $client->resolve($stored, 'myTrades::' . $sym);
        }
    }

    public function watch_orders(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_watch_orders(...))($outcome, $since, $limit, $params);
    }

    private function do_watch_orders(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * streams updates of the authenticated wallet's $orders over its per-account v3 $channel
         *
         * @see https://docs.sx.bet/api-reference/channel-$orders-v3
         *
         * @param {string} [$outcome] unified $outcome or $outcome token id to narrow the stream down to
         * @param {int} [$since] timestamp in ms of the earliest order to return
         * @param {int} [$limit] the maximum number of $orders to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of [prediction order structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
         */
        if ($this->walletAddress === null) {
            throw new ArgumentsRequired($this->id . ' watchOrders() requires a walletAddress');
        }
        $messageHash = 'orders';
        if ($outcome !== null) {
            Async\await($this->load_outcome($outcome));
            $outcomeObj = $this->outcome($outcome);
            $sym = $this->safe_string($outcomeObj, 'outcome');
            $messageHash = 'orders::' . $sym;
        }
        $channel = 'account:orders_v3_#' . $this->walletAddress;
        $orders = Async\await($this->subscribe_sxbet_channel($messageHash, $channel));
        return $this->filter_by_since_limit($orders, $since, $limit, 'timestamp', true);
    }

    public function handle_order(Client $client, array $rows) {
        //
        //     OrderV3 rows - identical to GET /orders-v3 (plus INACTIVE states with inactiveReason)
        //
        $rowsLength = count($rows);
        for ($i = 0; $i < $rowsLength; $i++) {
            $row = $this->safe_dict($rows[$i], 'order', $rows[$i]);
            $order = $this->parse_prediction_order($row);
            if ($this->orders === null) {
                $cacheLimit = $this->safe_integer($this->options, 'ordersLimit', 1000);
                $this->orders = new ArrayCacheByOutcomeById($cacheLimit);
            }
            $stored = $this->orders;
            $stored->append($order);
            $client->resolve($stored, 'orders');
            $sym = $this->safe_string($order, 'outcome');
            if ($sym !== null) {
                $client->resolve($stored, 'orders::' . $sym);
            }
        }
    }

    public function handle_errors(int $code, string $reason, string $url, string $method, array $headers, string $body, mixed $response, mixed $requestHeaders, mixed $requestBody) {
        // sx.bet returns { "error": "Bad Request", "message": <code or [strings]>, "statusCode": 4xx };
        // map the known codes to ccxt errors so callers can distinguish a rejected order or a
        // validation problem from a transport outage (the base otherwise maps a bare 4xx to the
        // exchange-not-available error). unmapped codes fall through to the base http-status handling
        if ($response === null) {
            return null;
        }
        $message = $this->safe_value($response, 'message');
        if ($message === null) {
            return null;
        }
        // validation failures arrive in string-array form, business errors in single-code-string form
        $messageString = null;
        if ((gettype($message) === 'array' && array_keys($message) === array_keys(array_keys($message)))) {
            $messageString = implode(', ', $message);
        } else {
            $messageString = $message;
        }
        $feedback = $this->id . ' ' . $body;
        $this->throw_exactly_matched_exception($this->exceptions['exact'], $messageString, $feedback);
        $this->throw_broadly_matched_exception($this->exceptions['broad'], $messageString, $feedback);
        // a 400 is a client-side bad request (bad params, invalid order), not a transport outage —
        // throw BadRequest instead of letting the base map the bare 400 to a retryable network-unavailable error
        if ($code === 400) {
            throw new BadRequest($feedback);
        }
        return null;
    }

    public function sign(mixed $path, mixed $api = 'sxbet', $method = 'GET', $params = array(), mixed $headers = null, mixed $body = null) {
        /**
         * @ignore
         * builds the request $url and attaches the x-sx-$api-key header; every private v3 route authenticates with the apiKey credential, so its absence fails fast instead of surfacing a raw 401
         * @param {string} $path the endpoint $path
         * @param {string|string[]} $api the $api group and access level
         * @param {string} $method the http $method
         * @param {array} $params the request parameters
         * @param {array} [$headers] request $headers
         * @param {string} [$body] the request $body
         * @return {array} a dict with $url, $method, $body and $headers
         */
        $apiGroup = gettype($api) === 'string' ? $api : $api[0];
        $accessLevel = gettype($api) === 'string' ? 'public' : $api[1];
        if (($accessLevel === 'private') && ($this->apiKey === null)) {
            throw new AuthenticationError($this->id . ' ' . $path . ' is a private endpoint and requires the apiKey credential (the x-sx-$api-key header)');
        }
        $baseUrls = $this->urls['api'];
        $baseUrl = $this->safe_string($baseUrls, $apiGroup, $baseUrls['sxbet']);
        $url = $baseUrl . '/' . $this->implode_params($path, $params);
        $query = $this->omit($params, $this->extract_params($path));
        $existingHeaders = ($headers !== null) ? $headers : array();
        $headers = $this->extend(array(
            'Accept' => 'application/json',
            'Content-Type' => 'application/json',
        ), $existingHeaders);
        if ($this->apiKey !== null) {
            $headers['x-sx-$api-key'] = $this->apiKey;
        }
        // DELETE /orders-v3 carries its order ids in a JSON body; the other DELETE routes -
        // /orders-v3/all and /orders-v3/event - take query parameters, like every GET
        $sendAsQuery = ($method === 'GET');
        if ($method === 'DELETE') {
            $hasOrdersList = (is_array($query) && array_key_exists('orders' ?? '', $query));
            $sendAsQuery = !$hasOrdersList;
        }
        if ($sendAsQuery) {
            $querystring = $this->urlencode($query);
            if ($querystring !== '') {
                $url .= '?' . $querystring;
            }
        } else {
            $queryKeys = is_array($query) ? array_keys($query) : array();
            $queryKeysLength = count($queryKeys);
            if ($queryKeysLength > 0) {
                $body = $this->json($query);
            }
        }
        return array( 'url' => $url, 'method' => $method, 'body' => $body, 'headers' => $headers );
    }
}
